let modelRouterInstance: ModelRouter | null = null;

/**
 * Get or create the singleton ModelRouter instance
 */
export function getModelRouter(config?: Partial<ModelRouterConfig>): ModelRouter {
  if (!modelRouterInstance) {
    modelRouterInstance = new ModelRouter(config);
  }
  return modelRouterInstance;
}

/**
 * Reset the singleton instance
 */
export function resetModelRouter(): void {
  modelRouterInstance = null;
}

/**
 * Create a new ModelRouter instance (non-singleton)
 */
export function createModelRouter(config?: Partial<ModelRouterConfig>): ModelRouter {
  return new ModelRouter(config);
}

// ============================================================================
// Convenience Functions
// ============================================================================

/**
 * Quick route function for common use case
 */
export async function routeToModel(task: string): Promise<ClaudeModel> {
  const router = getModelRouter();
  const result = await router.route(task);
  return result.model;
}

/**
 * Route with full result
 */
export async function routeToModelFull(
  task: string,
  embedding?: number[]
): Promise<ModelRoutingResult> {
  const router = getModelRouter();
  return router.route(task, embedding);
}

/**
 * Analyze task complexity without routing
 */
export function analyzeTaskComplexity(task: string): ComplexityAnalysis {
  const router = getModelRouter();
  return router.analyzeComplexity(task, undefined);
}

/**
 * Get model router statistics
 */
export function getModelRouterStats(): ReturnType<ModelRouter['getStats']> {
  const router = getModelRouter();
  return router.getStats();
}

/**
 * Record routing outcome for learning
 */
export function recordModelOutcome(
  task: string,
  model: ClaudeModel,
  outcome: 'success' | 'failure' | 'escalated'
): void {
  const router = getModelRouter();
  router.recordOutcome(task, model, outcome);
}

/**
 * ADR-149 — record an outcome keyed by the concrete model id rather than
 * the tier label. Updates the shadow `priorsById` state. Selection logic
 * still uses tier priors; this data accumulates for a future per-modelId
 * selector refactor.
 *
 * Safe to call alongside `recordModelOutcome` — they update independent
 * state slices so double-counting is impossible.
 */
export function recordModelOutcomeByModelId(
  task: string,
  modelId: string,
  outcome: 'success' | 'failure' | 'escalated'
): void {
  const router = getModelRouter();
  router.recordOutcomeByModelId(task, modelId, outcome);
}

/**
 * ADR-149 iter 14 — read-only access to the per-modelId Beta priors. The
 * neural-router consumes this to apply per-model Thompson sampling on top
 * of its predicted-quality vector when CLAUDE_FLOW_ROUTER_BANDIT_PER_MODEL=1.
 * Returns the legacy bucketed priors (`priorsById[bucket][modelId]`) when
 * present, else null.
 */
export function getModelRouterPriorsById(): Record<ComplexityBucket, Record<string, BetaPrior>> | null {
  const router = getModelRouter();
  const stats = router.getStats();
  return stats.priorsById ?? null;
}

/**
 * Re-export the complexity-bucket helper so the neural-router (which gets
 * the task text via the route() call) can map a complexity score to the
 * matching bandit bucket.
 */
export { complexityBucket };

/**
 * neural-router.ts — Optional cost-optimal neural routing path (ADR-148).
 *
 * Wires `@metaharness/router` (pure-TS k-NN/KRR + optional FastGRNN via
 * `@ruvector/tiny-dancer`) into the model-routing path as a graceful, gated
 * addition. The shipped heuristic + Thompson bandit stays as the default;
 * this module only contributes a decision when:
 *
 *   1. `CLAUDE_FLOW_ROUTER_NEURAL=1` is set
 *   2. Either a trained artifact path resolves (`CLAUDE_FLOW_ROUTER_MODEL_PATH`)
 *      OR the bundled seed corpus loads
 *   3. The dynamic `import('@metaharness/router')` succeeds
 *
 * Otherwise `tryCostOptimalRoute(...)` returns `null` and the caller falls
 * back to the bandit path with `routedBy: 'bandit-fallback'`.
 *
 * Observability — `routedBy` is returned on every result and must never be
 * inferred from "did the import resolve?" (ADR-074, ADR-086). It carries
 * exactly one of:
 *   - 'metaharness-knn'  pure-TS k-NN, no training (uses raw seed examples)
 *   - 'metaharness-krr'  pure-TS KRR with LOO-CV λ (TrainedRouter JSON)
 *   - 'fastgrnn'         native FastGRNN via tiny-dancer (NativeRouter)
 *
 * Performance — module-level caches resolve the backend, seed corpus and
 * router once per process. Hot path is a single `route(embedding)` call.
 *
 * @module neural-router
 */

import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve as resolvePath } from 'node:path';

import type { ClaudeModel } from './model-router.js';

// ============================================================================
// Public API
// ============================================================================

/** Backend identifier carried on every result (never inferred). */
export type NeuralRoutedBy = 'metaharness-knn' | 'metaharness-krr' | 'fastgrnn';

/** Cost-optimal route decision. */
export interface NeuralRouteResult {
  /** Chosen Claude tier label (back-compat). Derived from `modelId`. */
  model: ClaudeModel;
  /**
   * Concrete picked model id — ADR-149. May be an Anthropic SDK id or an
   * OpenRouter slug. Always a string; the closest tier label is in `model`
   * for back-compat with consumers that still expect ClaudeModel.
   */
  modelId: string;
  /** Predicted quality the chosen candidate is expected to achieve (0..1). */
  predictedQuality: number;
  /** Did the predicted quality clear the configured `qualityBar`? */
  metBar: boolean;
  /** Per-candidate predicted qualities, ordered cheapest-first. */
  alternatives: Array<{ model: ClaudeModel; modelId: string; predictedQuality: number; costPerMTok: number }>;
  /** Backend that produced the decision. */
  routedBy: NeuralRoutedBy;
  /** Inference latency in microseconds. */
  inferenceTimeUs: number;
  /**
   * ADR-149 iter 45 — ensemble disagreement diagnostic. Absolute difference
   * in predicted quality for the PICKED model between the unified KRR and
   * the bucket specialist (iter 16). Set only when both are loaded AND a
   * complexityBucket was supplied. Operators tuning iter 44's
   * `CLAUDE_FLOW_ROUTER_ENSEMBLE_UNCERTAINTY_THRESHOLD` need to observe
   * realistic disagreement values to pick a sensible cutoff.
   */
  ensembleDisagreement?: number;
}

/** Module-level configuration. Read once at first call from env. */
interface NeuralRouterConfig {
  enabled: boolean;
  modelPath?: string;
  /** Bundled fallback artifact (KRR JSON). Used when `modelPath` is unset. */
  bundledKrrPath: string;
  qualityBar: number;
  seedCorpusPath: string;
  /** k for k-NN backend (default 5). */
  k: number;
  /**
   * ADR-149 iter 12 — optional latency budget in ms. When > 0, candidates
   * whose measured p50 latency exceeds the budget are filtered OUT before
   * the cost-optimal selector runs. Default 0 (unbounded, cost-only).
   * For interactive flows that need sub-second responses, set 1000.
   */
  latencyBudgetMs: number;
  /**
   * ADR-149 iter 22+24 — post-hoc isotonic calibration. When the bundled
   * calibrator JSON is present, KRR predict() outputs are piped through
   * IsotonicCalibrator.transform() before cost-optimal selection.
   *
   * DEFAULT ON (iter 24, ADR-149). Iter 23's out-of-sample LOO validation
   * showed ECE drops from 0.1604 (POORLY-CALIBRATED) to 0.0335
   * (WELL-CALIBRATED) — a 79% reduction with only a 0.0144 train/test gap,
   * confirming the calibrator generalizes. Set
   * `CLAUDE_FLOW_ROUTER_CALIBRATE=0` to opt out and recover iter 0-21 raw
   * KRR behavior.
   */
  calibrateEnabled: boolean;
  /** Path to the bundled calibrator JSON (iter 22). */
  calibratorPath: string;
  /**
   * ADR-149 iter 29 — orthogonal selector mode: when > 0, filter candidates
   * by blended price ≤ ceiling, then pick the HIGHEST predicted quality
   * (not cheapest-above-bar). Lets ops with a hard budget cap ask "best
   * model under $X" instead of "cheapest above quality threshold". Default
   * 0 (disabled) preserves iter 0-28 cost-optimal-above-bar semantics.
   */
  costCeilingPerMTok: number;
  /**
   * ADR-149 iter 44 — ensemble-uncertainty-aware fallback. When > 0, the
   * selector queries BOTH the unified KRR and the bucket specialist for
   * the same query, then computes |unified_q - specialist_q| for the
   * picked model. If the disagreement exceeds this threshold, returns null
   * so the caller falls back to the bandit — same path as a 429/5xx API
   * error today, but triggered by prediction uncertainty instead.
   *
   * Typical values: 0.10 (mild — only the most uncertain predictions
   * fall back), 0.20 (aggressive — any meaningful ensemble disagreement
   * triggers fallback). 0 disables (default — preserves iter 0-43 behavior).
   */
  ensembleUncertaintyThreshold: number;
}

// ============================================================================
// Internal state (lazy, single-init)
// ============================================================================

type PureRouter = { route: (e: number[]) => { id: string; predictedQuality: number; costPerMTok: number; metBar: boolean }; predictAll: (e: number[]) => Array<{ id: string; predictedQuality: number; costPerMTok: number }> };

interface ResolvedBackend {
  /** True if `@metaharness/router` was importable. */
  available: boolean;
  /** Unified-corpus router (fallback). null when no corpus / artifact was loadable. */
  router: PureRouter | null;
  /**
   * ADR-149 iter 16 — per-bucket specialist KRR routers. When the caller
   * supplies a complexity bucket AND the matching artifact is present,
   * the specialist is preferred over the unified `router`. Each specialist
   * was trained only on rows from its tier so it predicts more accurately
   * for queries in that band.
   */
  routerByBucket?: Partial<Record<'low' | 'med' | 'high', PureRouter>>;
  /**
   * For the FastGRNN/native path: the loaded `NativeRouter` instance and the
   * pre-built per-candidate embeddings. Loaded ONCE at resolve time and
   * reused on every route() call — avoids the load/build overhead per call.
   */
  native?: {
    router: { route: (e: number[], cands: Array<{ id: string; embedding: number[]; costPerMTok?: number; successRate?: number }>) => Promise<{ id: string; confidence: number; uncertainty: number; useLightweight: boolean; costPerMTok?: number; inferenceTimeUs: number }> };
    candidates: Array<{ id: string; embedding: number[]; costPerMTok: number }>;
  };
  /** Which backend the router represents. */
  routedBy: NeuralRoutedBy | null;
  /** Reason string for diagnostics. */
  reason: string;
}

let _config: NeuralRouterConfig | null = null;
let _backend: ResolvedBackend | null = null;
let _initPromise: Promise<ResolvedBackend> | null = null;

const PRICES: Record<ClaudeModel, number> = {
  haiku: 1, sonnet: 3, opus: 15, inherit: 3,
};

// ADR-149 iter 12 — lazy load measured per-model latency (mean ms) from the
// most-recent FULL seed-corpus measurement file. Cached per-process.
// Returns an empty map if no measurement is available.
let _latencyMapPromise: Promise<Record<string, number>> | null = null;
function loadLatencyMap(): Promise<Record<string, number>> {
  if (_latencyMapPromise !== null) return _latencyMapPromise;
  _latencyMapPromise = (async () => {
    const result: Record<string, number> = {};
    try {
      const fs = await import('node:fs');
      const path = await import('node:path');
      const benchDir = path.resolve(process.cwd(), 'docs', 'benchmarks', 'runs');
      if (!fs.existsSync(benchDir)) return result;
      const files = fs.readdirSync(benchDir)
        .filter(f => f.startsWith('seed-corpus-') && f.endsWith('.json'))
        .sort().reverse();
      // Prefer a file with all three tiers populated (full measurement run);
      // fall back to newest if none qualify.
      let chosen: { perCandidate?: Array<{ id: string; latency_mean_ms?: number | null; cheap_avg_score?: number | null; mid_avg_score?: number | null; strong_avg_score?: number | null }> } | null = null;
      for (const f of files) {
        try {
          const data = JSON.parse(fs.readFileSync(path.join(benchDir, f), 'utf8'));
          const sample = data.perCandidate?.[0];
          if (sample && sample.cheap_avg_score != null && sample.mid_avg_score != null && sample.strong_avg_score != null) {
            chosen = data; break;
          }
          if (!chosen) chosen = data;
        } catch { /* skip */ }
      }
      for (const r of chosen?.perCandidate ?? []) {
        if (typeof r.latency_mean_ms === 'number' && r.latency_mean_ms > 0) {
          result[r.id] = r.latency_mean_ms;
        }
      }
    } catch { /* best-effort */ }
    return result;
  })();
  return _latencyMapPromise;
}

/**
 * ADR-149 — map a concrete OpenRouter / Anthropic model id back to the
 * closest ClaudeModel tier label for back-compat. Used to populate the
 * `model: ClaudeModel` field when the actual picked `modelId` is e.g.
 * `openai/gpt-4.1` or `inclusionai/ling-2.6-flash`.
 *
 * Mapping rule: substring-based. Anthropic ids carry the tier name;
 * other providers map to the tier whose role they play (cheap, mid, strong).
 * The map is intentionally non-exhaustive — unknown ids default to 'sonnet'
 * (the safest middle ground for an unrecognised candidate).
 */
function tierLabelForModelId(modelId: string): ClaudeModel {
  const id = modelId.toLowerCase();
  if (id.includes('haiku') || id.includes('ling-') || id.includes('flash-lite')
    || id.includes('nemotron-nano') || id.includes('ministral')
    || id.includes('llama-3.2-3b') || id.includes('llama-3.1-8b')) {
    return 'haiku';
  }
  if (id.includes('opus')) return 'opus';
  // Mid-tier: sonnet, gpt-4.1, gemini-flash, llama-70b, nemotron-super, etc.
  return 'sonnet';
}

// ============================================================================
// Config resolution
// ============================================================================

function getConfig(): NeuralRouterConfig {
  if (_config !== null) return _config;
  // Default seed-corpus path: bundled with the package. We resolve relative to
  // this file's location so it works both in src (tsc dev) and in the dist.
  // dist layout:  dist/src/ruvector/neural-router.js → assets at dist/assets/...
  // src layout:   src/ruvector/neural-router.ts     → assets at assets/...
  // We probe both candidate locations.
  let assetsDir: string;
  try {
    const here = dirname(fileURLToPath(import.meta.url));
    const candidates = [
      resolvePath(here, '..', '..', 'assets', 'model-router'),       // src/ruvector → src/assets/...
      resolvePath(here, '..', '..', '..', 'assets', 'model-router'), // dist/src/ruvector → dist/assets/...
      resolvePath(here, '..', '..', '..', '..', 'assets', 'model-router'), // safety net
    ];
    assetsDir = candidates.find(existsSync) ?? candidates[0];
  } catch {
    assetsDir = resolvePath(process.cwd(), 'v3', '@claude-flow', 'cli', 'assets', 'model-router');
  }

  _config = {
    enabled: process.env.CLAUDE_FLOW_ROUTER_NEURAL === '1',
    modelPath: process.env.CLAUDE_FLOW_ROUTER_MODEL_PATH || undefined,
    bundledKrrPath: join(assetsDir, 'seed-router.krr.json'),
    // ADR-149 v2 — measured against the richer code-context corpus
    // (gen-seed-corpus-v2.mjs). On that corpus, cheap models (Ling 2.6
    // Flash) deliver 75-93% on cheap/mid tasks and ~54% on strong tasks;
    // expensive models deliver 56-89% across tiers. Bar=0.50 lets cheap
    // models win cheap+mid (cost-optimal) but escalates to capable models
    // on strong queries where cheap predictions fall below the bar.
    // Override per-installation; 0.25 = always-cheapest, 0.70 = quality-strict.
    qualityBar: parseFloat(process.env.CLAUDE_FLOW_ROUTER_QUALITY_BAR ?? '0.50') || 0.50,
    seedCorpusPath: process.env.CLAUDE_FLOW_ROUTER_SEED_CORPUS
      ?? join(assetsDir, 'seed-rows.json'),
    k: parseInt(process.env.CLAUDE_FLOW_ROUTER_KNN_K ?? '5', 10) || 5,
    latencyBudgetMs: Math.max(0, parseInt(process.env.CLAUDE_FLOW_ROUTER_LATENCY_BUDGET_MS ?? '0', 10) || 0),
    // ADR-149 iter 24 — DEFAULT ON. Opt out with `=0`. Iter 23 OOS
    // validation: ECE 0.1604 → 0.0335 (-79%), well-calibrated.
    calibrateEnabled: process.env.CLAUDE_FLOW_ROUTER_CALIBRATE !== '0',
    // ADR-149 iter 29 — orthogonal selector mode. Blended $/Mtok ceiling;
    // 0 disables (preserves cost-optimal-above-bar). Typical values:
    //   $5    → cheap+mid tier only (Ling 2.6, Gemini Flash Lite, Llama 3.3, GPT-4.1)
    //   $20   → exclude Sonnet ($48 blended) and Opus ($240)
    //   $50   → exclude Opus only
    costCeilingPerMTok: Math.max(0, parseFloat(process.env.CLAUDE_FLOW_ROUTER_COST_CEILING_USD_PER_MTOK ?? '0') || 0),
    // iter 44 — ensemble disagreement threshold; 0 disables.
    ensembleUncertaintyThreshold: Math.max(0, parseFloat(process.env.CLAUDE_FLOW_ROUTER_ENSEMBLE_UNCERTAINTY_THRESHOLD ?? '0') || 0),
    calibratorPath: process.env.CLAUDE_FLOW_ROUTER_CALIBRATOR_PATH
      ?? join(assetsDir, 'seed-router.calibrator.json'),
  };
  return _config;
}

// ============================================================================
// Backend resolution (single-init, lazy)
// ============================================================================

/** DRACO row — the shape both pure-TS and FastGRNN backends consume. */
interface DracoRow {
  embedding: number[];
  scores: Record<string, number>;
}

function loadSeedCorpus(path: string): DracoRow[] | null {
  if (!existsSync(path)) return null;
  try {
    const raw = readFileSync(path, 'utf8');
    const data = JSON.parse(raw);
    if (!Array.isArray(data)) return null;
    // Light-touch validation: each row must have a numeric-array embedding and
    // a non-empty scores map. We do not coerce types — bad data should be
    // visible as a config bug, not silently routed around.
    for (const row of data) {
      if (!row || !Array.isArray(row.embedding) || row.embedding.length === 0) return null;
      if (!row.scores || typeof row.scores !== 'object') return null;
    }
    return data as DracoRow[];
  } catch {
    return null;
  }
}

async function resolveBackend(cfg: NeuralRouterConfig): Promise<ResolvedBackend> {
  // 1. Optional dep present?
  let mh: typeof import('@metaharness/router');
  try {
    mh = await import('@metaharness/router');
  } catch {
    return { available: false, router: null, routedBy: null, reason: '@metaharness/router not installed' };
  }

  // 2. If a trained-model path is set AND tiny-dancer is loadable, prefer FastGRNN.
  //    Load the NativeRouter ONCE here; reuse on every route() call.
  if (cfg.modelPath && existsSync(cfg.modelPath)) {
    const backend = await mh.resolveRouterBackend('auto');
    if (backend === 'native') {
      try {
        const nativeRouter = await mh.NativeRouter.load({ modelPath: cfg.modelPath });
        // Build per-candidate embeddings once. NativeRouter requires non-empty
        // candidate embeddings; we use a one-hot signature so the three tiers
        // are distinct in the FastGRNN's feature engineering. Dim is probed
        // from the seed corpus or falls back to 384 (MiniLM default).
        const seed = loadSeedCorpus(cfg.seedCorpusPath);
        const dim = seed?.[0]?.embedding.length ?? 384;
        const candidates = (['haiku', 'sonnet', 'opus'] as const).map((id, i) => {
          const v = new Array(dim).fill(0);
          v[i % dim] = 1;
          return { id, embedding: v, costPerMTok: PRICES[id] };
        });
        return {
          available: true,
          router: null, // The native path uses the `native` field below, not `router`.
          native: { router: nativeRouter, candidates },
          routedBy: 'fastgrnn',
          reason: `native router loaded from ${cfg.modelPath}`,
        };
      } catch (e) {
        // Fall through to pure-TS paths
      }
    }
  }

  // 3. Trained KRR JSON artifact path?
  if (cfg.modelPath && existsSync(cfg.modelPath) && cfg.modelPath.endsWith('.json')) {
    try {
      const json = JSON.parse(readFileSync(cfg.modelPath, 'utf8'));
      const trained = mh.TrainedRouter.fromJSON(json);
      // Pre-extract candidate ids+costs for predictAll
      const cands = json.candidates.map((c: { id: string; costPerMTok: number }) => ({ id: c.id, costPerMTok: c.costPerMTok }));
      return {
        available: true,
        router: {
          route: (e: number[]) => {
            const r = trained.route(e);
            return { id: r.id, predictedQuality: r.predictedQuality, costPerMTok: r.costPerMTok, metBar: r.metBar };
          },
          predictAll: (e: number[]) => cands.map((c: { id: string; costPerMTok: number }) => ({
            id: c.id, predictedQuality: trained.predict(c.id, e), costPerMTok: c.costPerMTok,
          })).sort((a: { costPerMTok: number }, b: { costPerMTok: number }) => a.costPerMTok - b.costPerMTok),
        },
        routedBy: 'metaharness-krr',
        reason: `KRR artifact loaded from ${cfg.modelPath}`,
      };
    } catch {
      // Fall through to k-NN
    }
  }

  // 3.5. No user artifact → try the bundled pre-trained KRR (~96kB, ~0.020 ms/route).
  if (existsSync(cfg.bundledKrrPath)) {
    try {
      // ADR-149 iter 22+24+25 — load isotonic calibrator(s) if the gate
      // isn't explicitly closed. Calibration is ON by default (iter 24);
      // iter 23's out-of-sample LOO validation showed ECE drops 79% with
      // calibration enabled. Iter 25 adds per-tier calibrators: when a
      // matching `seed-router.calibrator.{low,med,high}.json` exists,
      // bucket-specialist KRR routers are wrapped with the bucket-matched
      // calibrator (closes mid-tier residual ECE; mid in-sample MAE drops
      // 0.36 → 0.17 with tier-specific fit). Set
      // `CLAUDE_FLOW_ROUTER_CALIBRATE=0` to opt out of all calibration.
      type Cal = { transform: (x: number) => number };
      let unifiedCalibrator: Cal | null = null;
      const calibratorByBucket: Partial<Record<'low' | 'med' | 'high', Cal>> = {};
      const loadedCalibrators: string[] = [];
      if (cfg.calibrateEnabled) {
        const { IsotonicCalibrator } = await import('./router-calibrator.js');
        const loadCal = (path: string): Cal | null => {
          if (!existsSync(path)) return null;
          try {
            return IsotonicCalibrator.fromJSON(JSON.parse(readFileSync(path, 'utf8')));
          } catch { return null; }
        };
        unifiedCalibrator = loadCal(cfg.calibratorPath);
        if (unifiedCalibrator) loadedCalibrators.push('unified');
        // Per-tier — paths follow the iter 16 KRR specialist convention.
        const calDir = cfg.calibratorPath.replace(/seed-router\.calibrator\.json$/, '');
        for (const bucket of ['low', 'med', 'high'] as const) {
          const c = loadCal(`${calDir}seed-router.calibrator.${bucket}.json`);
          if (c) {
            calibratorByBucket[bucket] = c;
            loadedCalibrators.push(bucket);
          }
        }
      }
      const wrapWithCalibrator = (r: PureRouter, cal: Cal | null): PureRouter => {
        if (!cal) return r;
        return {
          route: (e) => {
            const result = r.route(e);
            return { ...result, predictedQuality: cal.transform(result.predictedQuality) };
          },
          predictAll: (e) => r.predictAll(e).map(c => ({ ...c, predictedQuality: cal.transform(c.predictedQuality) })),
        };
      };

      // Helper: load a TrainedRouter from a path and wrap it as a PureRouter.
      const loadKrr = (path: string): PureRouter | null => {
        if (!existsSync(path)) return null;
        try {
          const json = JSON.parse(readFileSync(path, 'utf8'));
          const trained = mh.TrainedRouter.fromJSON(json);
          const cands = json.candidates.map((c: { id: string; costPerMTok: number }) => ({ id: c.id, costPerMTok: c.costPerMTok }));
          return {
            route: (e: number[]) => {
              const r = trained.route(e);
              return { id: r.id, predictedQuality: r.predictedQuality, costPerMTok: r.costPerMTok, metBar: r.metBar };
            },
            predictAll: (e: number[]) => cands.map((c: { id: string; costPerMTok: number }) => ({
              id: c.id, predictedQuality: trained.predict(c.id, e), costPerMTok: c.costPerMTok,
            })).sort((a: { costPerMTok: number }, b: { costPerMTok: number }) => a.costPerMTok - b.costPerMTok),
          };
        } catch { return null; }
      };

      const unifiedRaw = loadKrr(cfg.bundledKrrPath);
      if (!unifiedRaw) throw new Error('failed to load unified KRR');
      const unified = wrapWithCalibrator(unifiedRaw, unifiedCalibrator);

      // ADR-149 iter 16 — load per-bucket specialists if present. Each is a
      // KRR fit only to its tier's rows (cheap → low.json, mid → med.json,
      // strong → high.json). When tryCostOptimalRoute is called with a
      // complexityBucket, the matching specialist is preferred over the
      // unified router.
      const bucketDir = cfg.bundledKrrPath.replace(/seed-router\.krr\.json$/, '');
      const routerByBucket: Partial<Record<'low' | 'med' | 'high', PureRouter>> = {};
      const loadedBuckets: string[] = [];
      for (const bucket of ['low', 'med', 'high'] as const) {
        const r = loadKrr(`${bucketDir}seed-router.krr.${bucket}.json`);
        if (r) {
          // iter 25 — prefer tier-specific calibrator for this bucket;
          // fall back to the unified calibrator when no specialist exists.
          routerByBucket[bucket] = wrapWithCalibrator(r, calibratorByBucket[bucket] ?? unifiedCalibrator);
          loadedBuckets.push(bucket);
        }
      }
      const calibratedNote = loadedCalibrators.length > 0
        ? ` (calibrated: ${loadedCalibrators.join('+')})`
        : '';
      const reason = loadedBuckets.length > 0
        ? `bundled KRR loaded from ${cfg.bundledKrrPath} + ${loadedBuckets.length} bucket specialist(s): ${loadedBuckets.join(', ')}${calibratedNote}`
        : `bundled KRR artifact loaded from ${cfg.bundledKrrPath}${calibratedNote}`;
      return {
        available: true,
        router: unified,
        ...(loadedBuckets.length > 0 ? { routerByBucket } : {}),
        routedBy: 'metaharness-krr',
        reason,
      };
    } catch {
      // Fall through to k-NN
    }
  }

  // 4. Pure-TS k-NN over the bundled seed corpus.
  const seed = loadSeedCorpus(cfg.seedCorpusPath);
  if (!seed || seed.length === 0) {
    return { available: true, router: null, routedBy: null, reason: `seed corpus missing or invalid at ${cfg.seedCorpusPath}` };
  }
  const router = mh.Router.fromExamples(seed, PRICES, { qualityBar: cfg.qualityBar, k: cfg.k });
  // Pre-build per-candidate views ONCE so predictAll() doesn't re-allocate
  // O(seed.length) objects per call. Sort by cost so the result is already in
  // cheapest-first order.
  const candIds = Object.keys(PRICES).filter(id => id !== 'inherit');
  const candidateViews = candIds
    .map(id => ({
      id,
      costPerMTok: PRICES[id as ClaudeModel],
      examples: seed.map(r => ({ embedding: r.embedding, quality: r.scores[id] ?? 0 })),
    }))
    .sort((a, b) => a.costPerMTok - b.costPerMTok);
  return {
    available: true,
    router: {
      route: (e: number[]) => {
        const r = router.route(e);
        return { id: r.id, predictedQuality: r.predictedQuality, costPerMTok: r.costPerMTok, metBar: r.metBar };
      },
      predictAll: (e: number[]) => candidateViews.map(c => ({
        id: c.id, predictedQuality: router.predict(c, e), costPerMTok: c.costPerMTok,
      })),
    },
    routedBy: 'metaharness-knn',
    reason: `k-NN over ${seed.length} seed rows`,
  };
}

async function getBackend(): Promise<ResolvedBackend> {
  if (_backend !== null) return _backend;
  if (_initPromise !== null) return _initPromise;
  const cfg = getConfig();
  _initPromise = resolveBackend(cfg).then(b => { _backend = b; return b; });
  return _initPromise;
}

// ============================================================================
// Public function
// ============================================================================

/**
 * Cost-optimal route via the optional neural backend. Returns `null` when the
 * neural path is disabled (gate closed), unavailable (deps missing), or
 * unconfigured (no corpus / artifact). Callers must fall back to the
 * heuristic+bandit path on null and tag the result `routedBy: 'bandit-fallback'`.
 *
 * @param embedding 384-dim (or matching corpus dim) query embedding
 * @returns NeuralRouteResult on success, or `null` when the path is inactive
 */
export async function tryCostOptimalRoute(
  embedding: number[],
  opts?: { complexityBucket?: 'low' | 'med' | 'high' }
): Promise<NeuralRouteResult | null> {
  const cfg = getConfig();
  if (!cfg.enabled) return null;
  if (!Array.isArray(embedding) || embedding.length === 0) return null;

  const backend = await getBackend();
  if (!backend.available || backend.routedBy === null) return null;

  const t0 = Number(process.hrtime.bigint() / 1000n); // microseconds
  try {
    if (backend.routedBy === 'fastgrnn') {
      // Native path: NativeRouter was loaded once at resolveBackend time;
      // candidates were precomputed. Hot path is one .route() call.
      if (!backend.native) return null;
      const res = await backend.native.router.route(embedding, backend.native.candidates);
      const modelId = res.id;
      const t1 = Number(process.hrtime.bigint() / 1000n);
      return {
        model: tierLabelForModelId(modelId),
        modelId,
        predictedQuality: 1 - res.uncertainty, // FastGRNN reports uncertainty, not quality directly
        metBar: !res.useLightweight && res.confidence >= cfg.qualityBar,
        alternatives: backend.native.candidates.map(c => ({
          model: tierLabelForModelId(c.id),
          modelId: c.id,
          predictedQuality: c.id === modelId ? res.confidence : 0,
          costPerMTok: c.costPerMTok,
        })),
        routedBy: 'fastgrnn',
        inferenceTimeUs: t1 - t0,
      };
    }

    // Pure-TS paths (k-NN or KRR) — ADR-149: ids are arbitrary strings,
    // not ClaudeModel tier names. `tierLabelForModelId` derives the
    // back-compat tier; `modelId` carries the concrete pick.
    //
    // ADR-149 iter 16 — when the caller supplies a complexity bucket AND a
    // per-bucket specialist KRR was loaded at backend resolution, prefer
    // the specialist over the unified router. Each specialist is trained
    // only on its tier's rows (looQuality 0.94 for cheap vs 0.71 unified)
    // so its predictions are sharper for queries in that band.
    const activeRouter = (opts?.complexityBucket && backend.routerByBucket?.[opts.complexityBucket])
      ?? backend.router;
    if (!activeRouter) return null;
    const allRaw = activeRouter.predictAll(embedding);

    // ADR-149 iter 14 — per-modelId Thompson sampling. When
    // CLAUDE_FLOW_ROUTER_BANDIT_PER_MODEL=1, perturb each candidate's
    // predicted quality by a Beta sample from its persisted per-modelId
    // prior. Lets the bandit learn "Ling outperforms Haiku-4.5 within
    // the cheap tier" without changing the neural backend's prediction.
    //
    // Density guard: only apply the perturbation when (α+β) > 4 for that
    // modelId (≥2 outcomes accumulated; cold-start Beta(1,1) gives α+β=2).
    // Otherwise the bandit's signal is uninformative noise and we'd
    // sabotage the well-trained neural prediction.
    let all = allRaw;
    if (process.env.CLAUDE_FLOW_ROUTER_BANDIT_PER_MODEL === '1') {
      try {
        const { getModelRouterPriorsById, sampleBeta } = await import('./model-router.js');
        const priorsById = getModelRouterPriorsById();
        const bucket = opts?.complexityBucket;   // ADR-149 iter 15
        if (priorsById) {
          // Cross-bucket shrinkage configuration (iter 57). When λ > 0,
          // bucket-specific priors with few samples blend toward the
          // marginal-across-buckets prior. Classic James-Stein-style
          // shrinkage: rich cells trust themselves, thin cells borrow
          // strength from neighbors. Default λ = 4 (set =0 to disable).
          const shrinkageLambda = Math.max(0, parseFloat(process.env.CLAUDE_FLOW_ROUTER_BANDIT_SHRINKAGE_LAMBDA ?? '4') || 0);
          all = allRaw.map(a => {
            // Compute marginal-across-buckets prior for this modelId ONCE
            // (used either as the primary prior OR as the shrinkage anchor).
            let alphaMarginal = 1, betaMarginal = 1;
            let marginalFound = false;
            for (const b of ['low', 'med', 'high'] as const) {
              const p = priorsById[b]?.[a.id];
              if (p) {
                alphaMarginal += p.alpha - 1;
                betaMarginal += p.beta - 1;
                marginalFound = true;
              }
            }

            let alpha: number, beta: number;
            if (bucket && priorsById[bucket]?.[a.id]) {
              // Bucket-specific prior exists — use it as the primary signal
              // (iter 15 sharpness). Iter 57: when shrinkage is enabled,
              // blend toward the marginal anchor based on specific-cell
              // sample richness. w_s = (n_s + 1) / (n_s + 1 + λ). At n_s=0
              // → mostly marginal; at n_s=large → mostly specific.
              const p = priorsById[bucket][a.id];
              const nSpecific = p.alpha + p.beta - 2;
              if (shrinkageLambda > 0 && marginalFound) {
                const wSpecific = (nSpecific + 1) / (nSpecific + 1 + shrinkageLambda);
                alpha = wSpecific * p.alpha + (1 - wSpecific) * alphaMarginal;
                beta  = wSpecific * p.beta  + (1 - wSpecific) * betaMarginal;
              } else {
                alpha = p.alpha;
                beta = p.beta;
              }
            } else if (marginalFound) {
              // Marginal fallback (iter 14) — no bucket-specific prior at all.
              alpha = alphaMarginal;
              beta = betaMarginal;
            } else {
              return a;
            }
            const samples = alpha + beta;
            if (samples <= 2) return a;  // hard floor — uniform prior has no signal
            // iter 52 — continuous warmup curve. Replaces iter 14's binary
            // density guard. Two curves available:
            //   default (iter 52):  blendFactor = 0.5 * min(1, (s-2)/WARMUP)
            //                       Capped at 0.5 → matches iter 14's
            //                       50/50 baseline at saturation.
            //   iter 53 opt-in:     blendFactor = (s-2) / (s + WARMUP)
            //                       Asymptotes to 1.0 as samples → ∞.
            //                       At s=1000 → bandit ~99% influence.
            //                       Use when you have lots of bandit data
            //                       and want it to dominate the neural prior.
            //                       Gate: CLAUDE_FLOW_ROUTER_BANDIT_FULL_INFLUENCE=1.
            const warmupRange = Math.max(1, parseFloat(process.env.CLAUDE_FLOW_ROUTER_BANDIT_WARMUP_RANGE ?? '8') || 8);
            const fullInfluence = process.env.CLAUDE_FLOW_ROUTER_BANDIT_FULL_INFLUENCE === '1';
            const banditScore = sampleBeta(alpha, beta);
            const blendFactor = fullInfluence
              ? (samples - 2) / (samples + warmupRange)
              : 0.5 * Math.min(1, (samples - 2) / warmupRange);
            return { ...a, predictedQuality: (1 - blendFactor) * a.predictedQuality + blendFactor * banditScore };
          });
        }
      } catch { /* best-effort */ }
    }

    // ADR-149 iter 12 — latency-aware filtering. When CLAUDE_FLOW_ROUTER_
    // LATENCY_BUDGET_MS is set, drop candidates whose measured latency
    // exceeds the budget BEFORE the cost-optimal pick. The unfiltered
    // alternatives stay on the result for observability — only the chosen
    // `modelId` is constrained.
    let main = activeRouter.route(embedding);
    // Re-derive `main` from the post-Thompson `all` list when per-modelId
    // is on (otherwise the bandit adjustment is invisible to the selector).
    if (process.env.CLAUDE_FLOW_ROUTER_BANDIT_PER_MODEL === '1') {
      const clearing = all.filter(a => a.predictedQuality >= cfg.qualityBar)
        .sort((a, b) => a.costPerMTok - b.costPerMTok);
      const pick = clearing[0] ?? [...all].sort((a, b) => b.predictedQuality - a.predictedQuality)[0];
      if (pick) {
        main = { id: pick.id, predictedQuality: pick.predictedQuality, costPerMTok: pick.costPerMTok, metBar: pick.predictedQuality >= cfg.qualityBar };
      }
    }
    if (cfg.latencyBudgetMs > 0) {
      const latency = await loadLatencyMap();
      const eligible = all.filter(a => {
        const lat = latency[a.id];
        return lat === undefined || lat <= cfg.latencyBudgetMs;
      });
      if (eligible.length > 0) {
        // Re-pick cheapest-clearing-bar among eligible
        const clearing = eligible.filter(a => a.predictedQuality >= cfg.qualityBar)
          .sort((a, b) => a.costPerMTok - b.costPerMTok);
        const pick = clearing[0] ?? [...eligible].sort((a, b) => b.predictedQuality - a.predictedQuality)[0];
        main = { id: pick.id, predictedQuality: pick.predictedQuality, costPerMTok: pick.costPerMTok, metBar: pick.predictedQuality >= cfg.qualityBar };
      }
      // else: every candidate exceeds the budget → fall back to the original pick
      //   (better to return a slow answer than no answer)
    }

    // ADR-149 iter 29 — quality-best-under-budget mode. When the cost
    // ceiling is set, OVERRIDE the cost-optimal-above-bar pick:
    //   1. filter candidates by costPerMTok ≤ ceiling
    //   2. sort by predictedQuality DESC
    //   3. pick the top one
    // qualityBar still informs `metBar` on the result for observability,
    // but does NOT filter the selection — the operator's hard constraint
    // is cost, and they want the best quality they can get under it.
    // If no candidate fits the ceiling, fall through to the existing pick
    // (better to return something than nothing — same policy as the
    // latency-budget fallback above).
    if (cfg.costCeilingPerMTok > 0) {
      const affordable = all.filter(a => a.costPerMTok <= cfg.costCeilingPerMTok);
      if (affordable.length > 0) {
        const pick = [...affordable].sort((a, b) => b.predictedQuality - a.predictedQuality)[0];
        main = {
          id: pick.id,
          predictedQuality: pick.predictedQuality,
          costPerMTok: pick.costPerMTok,
          metBar: pick.predictedQuality >= cfg.qualityBar,
        };
      }
    }

    // ADR-149 iter 44+45 — ensemble disagreement diagnostic + uncertainty-
    // aware fallback. When both the unified router and a bucket specialist
    // are loaded AND a bucket was supplied, compute the picked model's
    // prediction disagreement across both backends. ALWAYS surface it on
    // the result (iter 45 — observable signal for tuning the threshold).
    // If iter 44's threshold is > 0 AND the disagreement exceeds it, return
    // null so the caller falls back to the pure bandit path (same as 429/5xx
    // — uncertainty is a kind of soft failure).
    let ensembleDisagreement: number | undefined;
    if (
      opts?.complexityBucket
      && backend.routerByBucket?.[opts.complexityBucket]
      && backend.router
      && activeRouter !== backend.router            // we used the specialist; cross-check vs unified
    ) {
      const unifiedAlts = backend.router.predictAll(embedding);
      const specialistQ = main.predictedQuality;
      const unifiedQ = unifiedAlts.find(a => a.id === main.id)?.predictedQuality ?? specialistQ;
      ensembleDisagreement = Math.abs(unifiedQ - specialistQ);
      if (cfg.ensembleUncertaintyThreshold > 0 && ensembleDisagreement > cfg.ensembleUncertaintyThreshold) {
        return null;
      }
    }

    const t1 = Number(process.hrtime.bigint() / 1000n);
    return {
      model: tierLabelForModelId(main.id),
      modelId: main.id,
      predictedQuality: main.predictedQuality,
      metBar: main.metBar,
      alternatives: all.map(a => ({
        model: tierLabelForModelId(a.id),
        modelId: a.id,
        predictedQuality: a.predictedQuality,
        costPerMTok: a.costPerMTok,
      })),
      routedBy: backend.routedBy,
      inferenceTimeUs: t1 - t0,
      ...(ensembleDisagreement !== undefined ? { ensembleDisagreement } : {}),
    };
  } catch {
    // Any runtime failure is silently swallowed → caller's bandit-fallback engages.
    return null;
  }
}

/**
 * Batch counterpart to `tryCostOptimalRoute`. Routes a list of embeddings
 * in one go, sharing backend resolution + (for the pure-TS paths)
 * candidate-view setup across the batch. The native FastGRNN path still
 * dispatches per-call (xenova's worker doesn't support array inputs for
 * tiny-dancer's Router.route).
 *
 * Order of the output array matches the input order. Each slot is either
 * a NeuralRouteResult or null (gate closed, backend unavailable, etc. —
 * mirrors the single-call contract).
 *
 * For harness-style callers (batch evals, GAIA runs, parallel agent
 * dispatch) this amortizes backend init across N queries — first-call
 * cold-load (~10 ms) becomes a fixed cost regardless of batch size.
 */
export async function tryCostOptimalRouteBatch(embeddings: number[][]): Promise<Array<NeuralRouteResult | null>> {
  const out: Array<NeuralRouteResult | null> = new Array(embeddings.length).fill(null);
  const cfg = getConfig();
  if (!cfg.enabled) return out;
  const backend = await getBackend();
  if (!backend.available || backend.routedBy === null) return out;

  // FastGRNN path: per-call native dispatch. The native router doesn't
  // expose a batch entry point. We still share the loaded NativeRouter
  // instance + candidate embeddings, which is most of the per-call cost.
  if (backend.routedBy === 'fastgrnn') {
    if (!backend.native) return out;
    const native = backend.native;
    const tasks = embeddings.map(async (e, i) => {
      if (!Array.isArray(e) || e.length === 0) return null;
      try {
        const t0 = Number(process.hrtime.bigint() / 1000n);
        const res = await native.router.route(e, native.candidates);
        const modelId = res.id;
        const t1 = Number(process.hrtime.bigint() / 1000n);
        const result: NeuralRouteResult = {
          model: tierLabelForModelId(modelId),
          modelId,
          predictedQuality: 1 - res.uncertainty,
          metBar: !res.useLightweight && res.confidence >= cfg.qualityBar,
          alternatives: native.candidates.map(c => ({
            model: tierLabelForModelId(c.id),
            modelId: c.id,
            predictedQuality: c.id === modelId ? res.confidence : 0,
            costPerMTok: c.costPerMTok,
          })),
          routedBy: 'fastgrnn',
          inferenceTimeUs: t1 - t0,
        };
        out[i] = result;
      } catch {
        out[i] = null;
      }
      return null;
    });
    await Promise.all(tasks);
    return out;
  }

  // Pure-TS path (k-NN or KRR): same shared router + candidate views,
  // tight loop. predictAll is cheap (already-pre-built per-candidate
  // examples) so we avoid re-allocating per call.
  if (!backend.router) return out;
  for (let i = 0; i < embeddings.length; i++) {
    const e = embeddings[i];
    if (!Array.isArray(e) || e.length === 0) { out[i] = null; continue; }
    try {
      const t0 = Number(process.hrtime.bigint() / 1000n);
      const main = backend.router.route(e);
      const all = backend.router.predictAll(e);
      const t1 = Number(process.hrtime.bigint() / 1000n);
      out[i] = {
        model: tierLabelForModelId(main.id),
        modelId: main.id,
        predictedQuality: main.predictedQuality,
        metBar: main.metBar,
        alternatives: all.map(a => ({
          model: tierLabelForModelId(a.id),
          modelId: a.id,
          predictedQuality: a.predictedQuality,
          costPerMTok: a.costPerMTok,
        })),
        routedBy: backend.routedBy,
        inferenceTimeUs: t1 - t0,
      };
    } catch {
      out[i] = null;
    }
  }
  return out;
}

/**
 * Diagnostic surface — returns the active backend without performing a route.
 * Used by the bench and by `claude-flow neural router status` (future CLI).
 */
export async function neuralRouterStatus(): Promise<{ enabled: boolean; available: boolean; routedBy: NeuralRoutedBy | null; reason: string; config: NeuralRouterConfig }> {
  const cfg = getConfig();
  if (!cfg.enabled) return { enabled: false, available: false, routedBy: null, reason: 'CLAUDE_FLOW_ROUTER_NEURAL!=1', config: cfg };
  const backend = await getBackend();
  return { enabled: true, available: backend.available, routedBy: backend.routedBy, reason: backend.reason, config: cfg };
}

/**
 * ADR-149 iter 7 — fallback selector for retry-on-failure. Returns the
 * cheapest candidate predicted to clear the quality bar (or the best-
 * predicted if none do) that is NOT in `excludeModelIds`. Used by
 * `executeAgentTask` to retry with a different model after a 429/5xx.
 *
 * Returns `null` when:
 *   - the gate is closed (mirrors tryCostOptimalRoute)
 *   - the embedding is missing or empty
 *   - the backend isn't loadable
 *   - every candidate is excluded (all retries exhausted)
 *
 * Selection is per-candidate via predictAll, then filter by exclude,
 * then cheapest-clearing-bar (falling back to best-predicted).
 */
export async function nextCostOptimalAlternative(
  embedding: number[],
  excludeModelIds: Iterable<string>
): Promise<NeuralRouteResult | null> {
  const cfg = getConfig();
  if (!cfg.enabled) return null;
  if (!Array.isArray(embedding) || embedding.length === 0) return null;
  const backend = await getBackend();
  if (!backend.available || backend.router === null || backend.routedBy === null) return null;

  const exclude = new Set<string>(excludeModelIds);
  const t0 = Number(process.hrtime.bigint() / 1000n);

  // Pure-TS path only — fallback retries are too rare to be worth threading
  // through the FastGRNN candidate-embedding rebuild dance.
  try {
    const all = backend.router.predictAll(embedding);
    const remaining = all.filter(a => !exclude.has(a.id));
    if (remaining.length === 0) return null;

    // Cheapest predicted to clear qualityBar, else best-predicted among
    // remaining. Mirrors @metaharness/router's qualityBar semantics.
    const clearing = remaining.filter(a => a.predictedQuality >= cfg.qualityBar)
      .sort((a, b) => a.costPerMTok - b.costPerMTok);
    const pick = clearing[0] ?? [...remaining].sort((a, b) => b.predictedQuality - a.predictedQuality)[0];
    const t1 = Number(process.hrtime.bigint() / 1000n);

    return {
      model: tierLabelForModelId(pick.id),
      modelId: pick.id,
      predictedQuality: pick.predictedQuality,
      metBar: pick.predictedQuality >= cfg.qualityBar,
      alternatives: remaining.map(a => ({
        model: tierLabelForModelId(a.id),
        modelId: a.id,
        predictedQuality: a.predictedQuality,
        costPerMTok: a.costPerMTok,
      })),
      routedBy: backend.routedBy,
      inferenceTimeUs: t1 - t0,
    };
  } catch {
    return null;
  }
}

/**
 * Test seam — reset module-level caches so unit tests can simulate cold init.
 * Not exported from the package's barrel.
 */
export function __resetNeuralRouterForTests(): void {
  _config = null;
  _backend = null;
  _initPromise = null;
  _latencyMapPromise = null;
}

/**
 * output-verifier.ts — Confidence-gated tier escalation (post-generation).
 *
 * ADR-026/143 route tasks to a tier BEFORE generation. 2026 SOTA cascade
 * routing adds a post-generation gate: attempt the cheap tier, run a CHEAP
 * verifier over the produced output, and escalate to the next tier only when
 * the verifier is not confident. This module is that verifier.
 *
 * Design constraints (load-bearing):
 * - $0 by default — NO LLM call. Every signal is a structural / lexical
 *   check: emptiness, refusal patterns, truncation, delimiter balance,
 *   degenerate repetition, and (for code tasks) a real syntax parse via the
 *   TypeScript compiler (lazy-imported; degrades to delimiter checks when
 *   typescript is not installed) or JSON.parse for JSON output.
 * - Pure with respect to router state — recording the verdict into the
 *   bandit's learning stream is the CALLER's job (the hooks_model-verify
 *   MCP tool does it via ModelRouter.recordOutcome), keeping this module
 *   trivially unit-testable.
 * - Escalation ladder mirrors the tier table: tier 2 (haiku) → tier 3
 *   (sonnet), sonnet → opus, opus has no bump (escalate=false even when the
 *   verdict is not confident — the caller should retry or surface instead).
 *
 * Verdict semantics: `confident=false` means "cheap signals say this output
 * is likely unusable"; it is NOT a semantic-quality judgment. False
 * negatives (bad output that parses fine) are expected — this gate trades
 * recall for being free.
 *
 * @module ruvector/output-verifier
 */

export type VerifyTier = 1 | 2 | 3;
export type VerifyModel = 'haiku' | 'sonnet' | 'opus';
export type VerifyTaskKind = 'code' | 'json' | 'text' | 'auto';

export interface VerifyInput {
  /** The task the output was generated for. */
  task: string;
  /** The generated output to verify. */
  output: string;
  /** Model that produced the output (drives the escalation ladder). */
  model?: VerifyModel;
  /** Tier that produced the output; derived from `model` when absent. */
  tierUsed?: VerifyTier;
  /** Force the task kind; 'auto' (default) detects from task + output. */
  taskKind?: VerifyTaskKind;
  /** Minimum trimmed output length considered plausible (default 20). */
  minLength?: number;
}

export interface VerifySignal {
  name: string;
  ok: boolean;
  detail?: string;
}

export interface VerifyVerdict {
  confident: boolean;
  /** Fraction of signals that passed (0..1). */
  score: number;
  /** Human-readable failure reasons; empty when confident. */
  reasons: string[];
  /** Every signal evaluated, pass or fail. */
  signals: VerifySignal[];
  /** Tier the caller should use next: unchanged when confident, bumped 2→3 on failure. */
  suggestedTier: VerifyTier;
  /** Concrete next model on the ladder (haiku→sonnet→opus); null when no bump exists. */
  suggestedModel: VerifyModel | null;
  /** True when not confident AND a higher tier exists to escalate to. */
  escalate: boolean;
  /** Detected task kind after 'auto' resolution. */
  taskKind: Exclude<VerifyTaskKind, 'auto'>;
}

const MODEL_TIER: Record<VerifyModel, VerifyTier> = { haiku: 2, sonnet: 3, opus: 3 };
const NEXT_MODEL: Record<VerifyModel, VerifyModel | null> = {
  haiku: 'sonnet',
  sonnet: 'opus',
  opus: null,
};

// Refusal phrasings scanned near the start of the output. Anchored to the
// head so a legitimate answer that *discusses* refusals doesn't trip it.
const REFUSAL_HEAD_CHARS = 240;
const REFUSAL_PATTERNS: RegExp[] = [
  /\bI\s+(?:can(?:no|')t|cannot)\s+(?:help|assist|do|provide|comply|fulfill|complete|write|generate)\b/i,
  /\bI(?:'m| am)\s+(?:sorry|afraid)\b[\s\S]{0,60}\b(?:can(?:no|')t|cannot|unable)\b/i,
  /\bI(?:'m| am)\s+(?:unable|not able)\s+to\b/i,
  /\bI\s+(?:must|have to)\s+(?:decline|refuse)\b/i,
  /\bI\s+won'?t\s+be\s+able\s+to\b/i,
  /\bas an AI(?:\s+(?:language\s+)?model)?[,\s]+I\b/i,
];

// A trailing dangling operator / opener strongly suggests a mid-expression cutoff.
const TRUNCATION_TAIL = /(?:,|&&|\|\||=>|[+*/%=]|\(|\[|\{|\bconst|\blet|\bvar|\bfunction|\breturn|:)\s*$/;

interface ExtractedCode {
  lang: string;
  code: string;
}

/** Pull fenced code blocks out of markdown-ish output. */
export function extractCodeBlocks(output: string): ExtractedCode[] {
  const blocks: ExtractedCode[] = [];
  const re = /```([A-Za-z0-9_-]*)\n([\s\S]*?)```/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(output)) !== null) {
    blocks.push({ lang: (m[1] || '').toLowerCase(), code: m[2] });
  }
  return blocks;
}

/** Cheap stack-based bracket balance check that skips string/comment-ish content. */
export function bracketsBalanced(code: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = { ')': '(', ']': '[', '}': '{' };
  let inString: string | null = null;
  let inLineComment = false;
  let inBlockComment = false;
  for (let i = 0; i < code.length; i++) {
    const c = code[i];
    const next = code[i + 1];
    if (inLineComment) { if (c === '\n') inLineComment = false; continue; }
    if (inBlockComment) { if (c === '*' && next === '/') { inBlockComment = false; i++; } continue; }
    if (inString) {
      if (c === '\\') { i++; continue; }
      if (c === inString) inString = null;
      continue;
    }
    if (c === '/' && next === '/') { inLineComment = true; i++; continue; }
    if (c === '/' && next === '*') { inBlockComment = true; i++; continue; }
    if (c === '"' || c === "'" || c === '`') { inString = c; continue; }
    if (c === '(' || c === '[' || c === '{') stack.push(c);
    else if (c === ')' || c === ']' || c === '}') {
      if (stack.pop() !== pairs[c]) return false;
    }
  }
  return stack.length === 0;
}

const CODE_TASK_HINT = /\b(?:code|function|class|implement|refactor|typescript|javascript|python|script|method|api endpoint|unit test)\b/i;
const CODE_OUTPUT_HINT = /(?:^|\n)\s*(?:import\s|export\s|function\s|class\s|const\s|let\s|def\s|return\s)/;

function detectTaskKind(input: VerifyInput): Exclude<VerifyTaskKind, 'auto'> {
  if (input.taskKind && input.taskKind !== 'auto') return input.taskKind;
  if (/\bjson\b/i.test(input.task) && /^[\s]*[[{]/.test(input.output.trim())) return 'json';
  if (extractCodeBlocks(input.output).length > 0) return 'code';
  if (CODE_TASK_HINT.test(input.task) && CODE_OUTPUT_HINT.test(input.output)) return 'code';
  return 'text';
}

/**
 * Syntax-check a JS/TS snippet. Uses the TypeScript compiler when available
 * (transpileModule with reportDiagnostics catches syntactic errors without
 * type-checking — cheap, no program construction). Falls back to bracket
 * balance when typescript is not installed.
 */
async function checkCodeParses(code: string, lang: string): Promise<{ ok: boolean; detail?: string }> {
  if (lang === 'json') {
    try { JSON.parse(code); return { ok: true }; }
    catch (e) { return { ok: false, detail: `JSON.parse failed: ${e instanceof Error ? e.message : String(e)}` }; }
  }
  const jsLike = ['', 'js', 'jsx', 'ts', 'tsx', 'javascript', 'typescript', 'mjs', 'cjs'].includes(lang);
  if (!jsLike) {
    // Non-JS languages: bracket balance is the best free proxy we have.
    return bracketsBalanced(code)
      ? { ok: true, detail: `no parser for lang="${lang}"; delimiter check only` }
      : { ok: false, detail: `unbalanced delimiters in ${lang} block` };
  }
  try {
    const ts = (await import('typescript')).default;
    const result = ts.transpileModule(code, {
      reportDiagnostics: true,
      compilerOptions: { jsx: ts.JsxEmit.Preserve, allowJs: true },
    });
    const syntaxErrors = (result.diagnostics ?? []).filter(d => d.category === ts.DiagnosticCategory.Error);
    if (syntaxErrors.length > 0) {
      const first = syntaxErrors[0];
      const msg = ts.flattenDiagnosticMessageText(first.messageText, ' ');
      return { ok: false, detail: `syntax error: ${msg}` };
    }
    return { ok: true };
  } catch {
    // typescript not installed — graceful degradation, delimiter check only.
    return bracketsBalanced(code)
      ? { ok: true, detail: 'typescript unavailable; delimiter check only' }
      : { ok: false, detail: 'typescript unavailable; unbalanced delimiters' };
  }
}

/** Detect degenerate repetition (same non-trivial line repeated many times in a row). */
function isDegenerate(output: string): boolean {
  const lines = output.split('\n').map(l => l.trim()).filter(l => l.length > 8);
  let run = 1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === lines[i - 1]) {
      run++;
      if (run >= 5) return true;
    } else {
      run = 1;
    }
  }
  return false;
}

/**
 * Compute a confidence verdict for `output` from cheap structural signals,
 * and suggest an escalation target when not confident.
 */
export async function verifyAndEscalate(input: VerifyInput): Promise<VerifyVerdict> {
  const output = input.output ?? '';
  const trimmed = output.trim();
  const minLength = input.minLength ?? 20;
  const taskKind = detectTaskKind(input);
  const model: VerifyModel = input.model ?? 'haiku';
  const tierUsed: VerifyTier = input.tierUsed ?? MODEL_TIER[model] ?? 2;

  const signals: VerifySignal[] = [];
  const reasons: string[] = [];
  const fail = (name: string, detail: string) => {
    signals.push({ name, ok: false, detail });
    reasons.push(`${name}: ${detail}`);
  };
  const pass = (name: string, detail?: string) => signals.push({ name, ok: true, detail });

  // 1. Emptiness
  if (trimmed.length === 0) fail('empty-output', 'output is empty or whitespace-only');
  else pass('empty-output');

  // 2. Plausible length (skip when already flagged empty)
  if (trimmed.length > 0 && trimmed.length < minLength) {
    fail('too-short', `output is ${trimmed.length} chars (< ${minLength})`);
  } else if (trimmed.length > 0) {
    pass('too-short');
  }

  // 3. Refusal patterns near the head
  const head = trimmed.slice(0, REFUSAL_HEAD_CHARS);
  const refusal = REFUSAL_PATTERNS.find(p => p.test(head));
  if (refusal) fail('refusal', `refusal pattern near start of output (${refusal.source.slice(0, 40)}…)`);
  else pass('refusal');

  // 4. Truncation: unclosed code fence, or dangling operator/opener at the tail
  const fenceCount = (output.match(/```/g) ?? []).length;
  if (fenceCount % 2 !== 0) {
    fail('truncation', 'unclosed code fence (odd number of ``` markers)');
  } else if (trimmed.length > 0 && TRUNCATION_TAIL.test(trimmed)) {
    fail('truncation', `output ends mid-expression ("…${trimmed.slice(-24).replace(/\n/g, '\\n')}")`);
  } else {
    pass('truncation');
  }

  // 5. Degenerate repetition
  if (isDegenerate(trimmed)) fail('degenerate-repetition', 'same line repeated 5+ times consecutively');
  else pass('degenerate-repetition');

  // 6. Code / JSON parse checks
  if (taskKind === 'code' || taskKind === 'json') {
    const blocks = extractCodeBlocks(output);
    const targets: ExtractedCode[] = blocks.length > 0
      ? blocks
      : [{ lang: taskKind === 'json' ? 'json' : '', code: output }];
    let allOk = true;
    const details: string[] = [];
    for (const block of targets) {
      const check = await checkCodeParses(block.code, taskKind === 'json' ? 'json' : block.lang);
      if (!check.ok) {
        allOk = false;
        details.push(check.detail ?? 'parse failed');
      } else if (check.detail) {
        details.push(check.detail);
      }
    }
    if (allOk) pass('code-parses', details.join('; ') || undefined);
    else fail('code-parses', details.join('; '));
  }

  const passed = signals.filter(s => s.ok).length;
  const score = signals.length > 0 ? passed / signals.length : 0;
  const confident = reasons.length === 0;

  const nextModel = NEXT_MODEL[model] ?? null;
  const suggestedModel = confident ? null : nextModel;
  const suggestedTier: VerifyTier = confident
    ? tierUsed
    : (nextModel !== null ? (Math.min(3, tierUsed + 1) as VerifyTier) : tierUsed);
  const escalate = !confident && nextModel !== null;

  if (!confident && nextModel === null) {
    reasons.push('already-at-top-tier: no higher tier to escalate to — retry or surface to the user');
  }

  return { confident, score, reasons, signals, suggestedTier, suggestedModel, escalate, taskKind };
}

export default verifyAndEscalate;

/**
 * Q-Learning Router for Task Routing
 *
 * Uses reinforcement learning to optimize task routing decisions
 * based on historical performance and context.
 *
 * Features:
 * - Caching for repeated task patterns (LRU cache)
 * - Optimized state space with feature hashing
 * - Epsilon decay with exponential annealing
 * - Experience replay buffer for stable learning
 * - Model persistence to .swarm/q-learning-model.json
 *
 * @module q-learning-router
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname, join } from 'path';

/**
 * Q-Learning Router Configuration
 */
export interface QLearningRouterConfig {
  /** Learning rate (default: 0.1) */
  learningRate: number;
  /** Discount factor (default: 0.99) */
  gamma: number;
  /** Initial exploration rate (default: 1.0) */
  explorationInitial: number;
  /** Final exploration rate (default: 0.01) */
  explorationFinal: number;
  /** Exploration decay steps (default: 10000) */
  explorationDecay: number;
  /** Exploration decay type (default: 'exponential') */
  explorationDecayType: 'linear' | 'exponential' | 'cosine';
  /** Maximum states in Q-table (default: 10000) */
  maxStates: number;
  /** Number of actions/routes (default: 8) */
  numActions: number;
  /** Experience replay buffer size (default: 1000) */
  replayBufferSize: number;
  /** Mini-batch size for replay (default: 32) */
  replayBatchSize: number;
  /** Enable experience replay (default: true) */
  enableReplay: boolean;
  /** Route cache size (default: 256) */
  cacheSize: number;
  /** Cache TTL in milliseconds (default: 300000 = 5 minutes) */
  cacheTTL: number;
  /** Model persistence path (default: '.swarm/q-learning-model.json') */
  modelPath: string;
  /** Auto-save interval in updates (default: 100) */
  autoSaveInterval: number;
  /** State space dimensionality for feature hashing (default: 64) */
  stateSpaceDim: number;
}

/**
 * Route decision result
 */
export interface RouteDecision {
  /** Selected route/action */
  route: string;
  /** Confidence score (0-1) */
  confidence: number;
  /** Q-values for all routes */
  qValues: number[];
  /** Was exploration used */
  explored: boolean;
  /** Route alternatives */
  alternatives: Array<{ route: string; score: number }>;
}

/**
 * Q-table entry
 */
interface QEntry {
  qValues: Float32Array;
  visits: number;
  lastUpdate: number;
  /** Eligibility trace for TD(lambda) */
  eligibility?: Float32Array;
}

/**
 * Experience tuple for replay buffer
 */
interface Experience {
  stateKey: string;
  actionIdx: number;
  reward: number;
  nextStateKey: string | null;
  timestamp: number;
  priority: number;
}

/**
 * Cache entry for route decisions
 */
interface CacheEntry {
  decision: RouteDecision;
  timestamp: number;
  hits: number;
}

/**
 * Persisted model structure
 */
interface PersistedModel {
  version: string;
  /**
   * State-key encoder version. v1 was the 31-bit truncating fold that
   * silently discarded the keyword block (features 0–31). v2 is a lossless
   * 32-bit FNV-1a fold over the full quantized vector. See #2239.
   *
   * On version mismatch, the qTable is reset (keys are computed with the old
   * encoder and would never be matched by new lookups); stats/epsilon are kept.
   */
  encoderVersion?: number;
  config: Partial<QLearningRouterConfig>;
  qTable: Record<string, { qValues: number[]; visits: number }>;
  stats: {
    stepCount: number;
    updateCount: number;
    avgTDError: number;
    epsilon: number;
  };
  metadata: {
    savedAt: string;
    totalExperiences: number;
  };
}

/** Current state-key encoder version (see PersistedModel.encoderVersion). */
const ENCODER_VERSION = 2;

/**
 * Default configuration
 */
const DEFAULT_CONFIG: QLearningRouterConfig = {
  learningRate: 0.1,
  gamma: 0.99,
  explorationInitial: 1.0,
  explorationFinal: 0.01,
  explorationDecay: 10000,
  explorationDecayType: 'exponential',
  maxStates: 10000,
  numActions: 8,
  replayBufferSize: 1000,
  replayBatchSize: 32,
  enableReplay: true,
  cacheSize: 256,
  cacheTTL: 300000,
  modelPath: '.swarm/q-learning-model.json',
  autoSaveInterval: 100,
  stateSpaceDim: 64,
};

/**
 * Route names mapping
 */
const ROUTE_NAMES = [
  'coder',
  'tester',
  'reviewer',
  'architect',
  'researcher',
  'optimizer',
  'debugger',
  'documenter',
];

/**
 * Task feature keywords for state representation
 */
const FEATURE_KEYWORDS = [
  // Code-related
  'implement', 'code', 'write', 'create', 'build', 'develop',
  // Testing-related
  'test', 'spec', 'coverage', 'unit', 'integration', 'e2e',
  // Review-related
  'review', 'check', 'audit', 'analyze', 'inspect',
  // Architecture-related
  'architect', 'design', 'structure', 'pattern', 'system',
  // Research-related
  'research', 'investigate', 'explore', 'find', 'search',
  // Optimization-related
  'optimize', 'performance', 'speed', 'memory', 'improve',
  // Debug-related
  'debug', 'fix', 'bug', 'error', 'issue', 'problem',
  // Documentation-related
  'document', 'docs', 'readme', 'comment', 'explain',
];

/**
 * Q-Learning Router for intelligent task routing
 *
 * Optimized with:
 * - LRU cache for repeated task patterns
 * - Feature hashing for efficient state space
 * - Exponential epsilon decay
 * - Prioritized experience replay
 * - Model persistence
 */
export class QLearningRouter {
  private config: QLearningRouterConfig;
  private qTable: Map<string, QEntry> = new Map();
  private epsilon: number;
  private stepCount = 0;
  private updateCount = 0;
  private avgTDError = 0;
  private ruvectorEngine: unknown = null;
  private useNative = false;

  // Experience replay buffer (circular buffer)
  private replayBuffer: Experience[] = [];
  private replayBufferIdx = 0;
  private totalExperiences = 0;

  // LRU cache for route decisions
  private routeCache: Map<string, CacheEntry> = new Map();
  private cacheOrder: string[] = [];
  private cacheHits = 0;
  private cacheMisses = 0;

  // Feature hash cache for state representation
  private featureHashCache: Map<string, Float32Array> = new Map();

  constructor(config: Partial<QLearningRouterConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.epsilon = this.config.explorationInitial;
  }

  /**
   * Initialize the router, attempting to load ruvector native module
   * and restore persisted model if available
   */
  async initialize(): Promise<void> {
    try {
      const ruvector = await import('@ruvector/core');
      this.ruvectorEngine = (ruvector as any).createQLearning?.(this.config);
      this.useNative = !!this.ruvectorEngine;
    } catch {
      // Fallback to JS implementation
      this.useNative = false;
    }

    // Try to load persisted model
    await this.loadModel();
  }

  /**
   * Load model from persistence file
   */
  async loadModel(path?: string): Promise<boolean> {
    const modelPath = path || this.config.modelPath;
    try {
      if (!existsSync(modelPath)) {
        return false;
      }
      const data = readFileSync(modelPath, 'utf-8');
      const model: PersistedModel = JSON.parse(data);

      // Validate version compatibility
      if (!model.version || !model.version.startsWith('1.')) {
        console.warn(`[Q-Learning] Incompatible model version: ${model.version}`);
        return false;
      }

      // #2239 — Encoder-version migration guard. v1 state keys were computed
      // by a fold that silently dropped the keyword block, so they cannot be
      // matched by v2 lookups. Skip the qTable import on mismatch (keep
      // stats/epsilon so learning curve survives a restart).
      const persistedEncoder = model.encoderVersion ?? 1;
      if (persistedEncoder === ENCODER_VERSION) {
        this.import(model.qTable);
      } else {
        console.warn(
          `[Q-Learning] Encoder version mismatch (persisted=${persistedEncoder}, current=${ENCODER_VERSION}); resetting Q-table (see #2239).`,
        );
      }

      // Restore stats
      this.stepCount = model.stats.stepCount || 0;
      this.updateCount = model.stats.updateCount || 0;
      this.avgTDError = model.stats.avgTDError || 0;
      this.epsilon = model.stats.epsilon || this.config.explorationInitial;
      this.totalExperiences = model.metadata?.totalExperiences || 0;

      return true;
    } catch (err) {
      console.warn(`[Q-Learning] Failed to load model: ${err}`);
      return false;
    }
  }

  /**
   * Save model to persistence file
   */
  async saveModel(path?: string): Promise<boolean> {
    const modelPath = path || this.config.modelPath;
    try {
      // Ensure directory exists
      const dir = dirname(modelPath);
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }

      const model: PersistedModel = {
        version: '1.0.0',
        encoderVersion: ENCODER_VERSION, // #2239
        config: {
          learningRate: this.config.learningRate,
          gamma: this.config.gamma,
          explorationDecayType: this.config.explorationDecayType,
          numActions: this.config.numActions,
        },
        qTable: this.export(),
        stats: {
          stepCount: this.stepCount,
          updateCount: this.updateCount,
          avgTDError: this.avgTDError,
          epsilon: this.epsilon,
        },
        metadata: {
          savedAt: new Date().toISOString(),
          totalExperiences: this.totalExperiences,
        },
      };

      writeFileSync(modelPath, JSON.stringify(model, null, 2));
      return true;
    } catch (err) {
      console.warn(`[Q-Learning] Failed to save model: ${err}`);
      return false;
    }
  }

  /**
   * Route a task based on its context
   * Uses LRU cache for repeated task patterns
   */
  route(taskContext: string, explore: boolean = true): RouteDecision {
    const stateKey = this.hashStateOptimized(taskContext);

    // Check cache first (only for exploitation, not exploration)
    if (!explore) {
      const cached = this.getCachedRoute(stateKey);
      if (cached) {
        this.cacheHits++;
        return cached;
      }
      this.cacheMisses++;
    }

    // Check if we should explore using decayed epsilon
    const shouldExplore = explore && Math.random() < this.epsilon;

    let actionIdx: number;
    let qValues: number[];

    if (shouldExplore) {
      // Random exploration
      actionIdx = Math.floor(Math.random() * this.config.numActions);
      qValues = this.getQValues(stateKey);
    } else {
      // Exploit - choose best action
      qValues = this.getQValues(stateKey);
      actionIdx = this.argmax(qValues);
    }

    // Calculate confidence from softmax of Q-values
    const confidence = this.softmaxConfidence(qValues, actionIdx);

    // Get alternatives sorted by Q-value
    const alternatives = ROUTE_NAMES
      .map((route, idx) => ({ route, score: qValues[idx] }))
      .sort((a, b) => b.score - a.score)
      .slice(1, 4); // Top 3 alternatives

    const decision: RouteDecision = {
      route: ROUTE_NAMES[actionIdx] || 'coder',
      confidence,
      qValues,
      explored: shouldExplore,
      alternatives,
    };

    // Cache the decision for exploitation queries
    if (!shouldExplore) {
      this.cacheRoute(stateKey, decision);
    }

    return decision;
  }

  /**
   * Get cached route decision (LRU cache)
   */
  private getCachedRoute(stateKey: string): RouteDecision | null {
    const entry = this.routeCache.get(stateKey);
    if (!entry) {
      return null;
    }

    // Check TTL
    if (Date.now() - entry.timestamp > this.config.cacheTTL) {
      this.routeCache.delete(stateKey);
      this.cacheOrder = this.cacheOrder.filter(k => k !== stateKey);
      return null;
    }

    // Update LRU order
    this.cacheOrder = this.cacheOrder.filter(k => k !== stateKey);
    this.cacheOrder.push(stateKey);
    entry.hits++;

    return entry.decision;
  }

  /**
   * Cache a route decision (LRU eviction)
   */
  private cacheRoute(stateKey: string, decision: RouteDecision): void {
    // Evict oldest if cache is full
    while (this.routeCache.size >= this.config.cacheSize && this.cacheOrder.length > 0) {
      const oldest = this.cacheOrder.shift();
      if (oldest) {
        this.routeCache.delete(oldest);
      }
    }

    this.routeCache.set(stateKey, {
      decision,
      timestamp: Date.now(),
      hits: 0,
    });
    this.cacheOrder.push(stateKey);
  }

  /**
   * Invalidate cache (call after significant Q-table updates)
   */
  invalidateCache(): void {
    this.routeCache.clear();
    this.cacheOrder = [];
  }

  /** Invalidate a single state's cached route (called after its Q-values change
   * so the next route() reflects the update immediately). */
  private invalidateCacheEntry(stateKey: string): void {
    if (this.routeCache.delete(stateKey)) {
      this.cacheOrder = this.cacheOrder.filter(k => k !== stateKey);
    }
  }

  /**
   * Update Q-values based on feedback
   * Includes experience replay for stable learning
   */
  update(taskContext: string, action: string, reward: number, nextContext?: string): number {
    const stateKey = this.hashStateOptimized(taskContext);
    const actionIdx = ROUTE_NAMES.indexOf(action);

    if (actionIdx === -1) {
      return 0;
    }

    const nextStateKey = nextContext ? this.hashStateOptimized(nextContext) : null;

    // Store experience in replay buffer
    if (this.config.enableReplay) {
      const experience: Experience = {
        stateKey,
        actionIdx,
        reward,
        nextStateKey,
        timestamp: Date.now(),
        priority: Math.abs(reward) + 0.1, // Initial priority based on reward magnitude
      };
      this.addToReplayBuffer(experience);
    }

    // Perform direct update
    const tdError = this.updateQValue(stateKey, actionIdx, reward, nextStateKey);

    // #cache-staleness: invalidate THIS state's cached route immediately. The
    // periodic full invalidation (every 50 updates) otherwise left a freshly
    // learned Q-update hidden behind a stale cached decision, so feedback
    // appeared to have no effect on routing until 50 updates accumulated.
    this.invalidateCacheEntry(stateKey);

    // Perform experience replay
    if (this.config.enableReplay && this.replayBuffer.length >= this.config.replayBatchSize) {
      this.experienceReplay();
    }

    // Decay exploration using configured strategy
    this.stepCount++;
    this.epsilon = this.calculateEpsilon();

    // Prune Q-table if needed
    if (this.qTable.size > this.config.maxStates) {
      this.pruneQTable();
    }

    this.updateCount++;
    this.avgTDError = (this.avgTDError * (this.updateCount - 1) + Math.abs(tdError)) / this.updateCount;

    // Auto-save periodically
    if (this.config.autoSaveInterval > 0 && this.updateCount % this.config.autoSaveInterval === 0) {
      this.saveModel().catch(() => {}); // Fire and forget
    }

    // Invalidate cache periodically to reflect Q-table changes
    if (this.updateCount % 50 === 0) {
      this.invalidateCache();
    }

    return tdError;
  }

  /**
   * Internal Q-value update
   */
  private updateQValue(stateKey: string, actionIdx: number, reward: number, nextStateKey: string | null): number {
    const entry = this.getOrCreateEntry(stateKey);
    const currentQ = entry.qValues[actionIdx];

    // Calculate target Q-value
    let targetQ: number;
    if (nextStateKey) {
      const nextQValues = this.getQValues(nextStateKey);
      const maxNextQ = Math.max(...nextQValues);
      targetQ = reward + this.config.gamma * maxNextQ;
    } else {
      // Terminal state
      targetQ = reward;
    }

    // TD error
    const tdError = targetQ - currentQ;

    // Update Q-value
    entry.qValues[actionIdx] += this.config.learningRate * tdError;
    entry.visits++;
    entry.lastUpdate = Date.now();

    return tdError;
  }

  /**
   * Add experience to circular replay buffer
   */
  private addToReplayBuffer(experience: Experience): void {
    if (this.replayBuffer.length < this.config.replayBufferSize) {
      this.replayBuffer.push(experience);
    } else {
      this.replayBuffer[this.replayBufferIdx] = experience;
    }
    this.replayBufferIdx = (this.replayBufferIdx + 1) % this.config.replayBufferSize;
    this.totalExperiences++;
  }

  /**
   * Perform prioritized experience replay
   * Samples mini-batch from buffer and updates Q-values
   */
  private experienceReplay(): void {
    if (this.replayBuffer.length < this.config.replayBatchSize) {
      return;
    }

    // Prioritized sampling based on TD error magnitude
    const batch = this.samplePrioritizedBatch(this.config.replayBatchSize);

    for (const exp of batch) {
      const tdError = this.updateQValue(exp.stateKey, exp.actionIdx, exp.reward, exp.nextStateKey);

      // Update priority for future sampling
      exp.priority = Math.abs(tdError) + 0.01; // Small constant to avoid zero priority
    }
  }

  /**
   * Sample a prioritized batch from replay buffer
   * Uses proportional prioritization
   */
  private samplePrioritizedBatch(batchSize: number): Experience[] {
    const totalPriority = this.replayBuffer.reduce((sum, exp) => sum + exp.priority, 0);
    const batch: Experience[] = [];
    const selected = new Set<number>();

    while (batch.length < batchSize && selected.size < this.replayBuffer.length) {
      let threshold = Math.random() * totalPriority;
      let cumSum = 0;

      for (let i = 0; i < this.replayBuffer.length; i++) {
        if (selected.has(i)) continue;

        cumSum += this.replayBuffer[i].priority;
        if (cumSum >= threshold) {
          batch.push(this.replayBuffer[i]);
          selected.add(i);
          break;
        }
      }
    }

    return batch;
  }

  /**
   * Calculate epsilon using configured decay strategy
   */
  private calculateEpsilon(): number {
    const { explorationInitial, explorationFinal, explorationDecay, explorationDecayType } = this.config;
    const progress = Math.min(this.stepCount / explorationDecay, 1.0);

    switch (explorationDecayType) {
      case 'linear':
        return explorationFinal + (explorationInitial - explorationFinal) * (1 - progress);

      case 'exponential':
        // Exponential decay: epsilon = final + (initial - final) * exp(-decay_rate * step)
        const decayRate = -Math.log((explorationFinal / explorationInitial) + 1e-8) / explorationDecay;
        return explorationFinal + (explorationInitial - explorationFinal) * Math.exp(-decayRate * this.stepCount);

      case 'cosine':
        // Cosine annealing: smooth transition
        return explorationFinal + (explorationInitial - explorationFinal) * 0.5 * (1 + Math.cos(Math.PI * progress));

      default:
        return Math.max(explorationFinal, explorationInitial - this.stepCount / explorationDecay);
    }
  }

  /**
   * Get statistics including cache and replay buffer metrics
   */
  getStats(): Record<string, number> {
    const cacheHitRate = this.cacheHits + this.cacheMisses > 0
      ? this.cacheHits / (this.cacheHits + this.cacheMisses)
      : 0;

    return {
      updateCount: this.updateCount,
      qTableSize: this.qTable.size,
      epsilon: this.epsilon,
      avgTDError: this.avgTDError,
      stepCount: this.stepCount,
      useNative: this.useNative ? 1 : 0,
      // Cache metrics
      cacheSize: this.routeCache.size,
      cacheHits: this.cacheHits,
      cacheMisses: this.cacheMisses,
      cacheHitRate,
      // Replay buffer metrics
      replayBufferSize: this.replayBuffer.length,
      totalExperiences: this.totalExperiences,
      // Feature hash cache
      featureHashCacheSize: this.featureHashCache.size,
    };
  }

  /**
   * Reset the router (clears all learned data)
   */
  reset(): void {
    this.qTable.clear();
    this.epsilon = this.config.explorationInitial;
    this.stepCount = 0;
    this.updateCount = 0;
    this.avgTDError = 0;

    // Reset replay buffer
    this.replayBuffer = [];
    this.replayBufferIdx = 0;
    this.totalExperiences = 0;

    // Reset cache
    this.routeCache.clear();
    this.cacheOrder = [];
    this.cacheHits = 0;
    this.cacheMisses = 0;

    // Reset feature hash cache
    this.featureHashCache.clear();
  }

  /**
   * Export Q-table for persistence
   */
  export(): Record<string, { qValues: number[]; visits: number }> {
    const result: Record<string, { qValues: number[]; visits: number }> = {};
    for (const [key, entry] of this.qTable) {
      result[key] = {
        qValues: Array.from(entry.qValues),
        visits: entry.visits,
      };
    }
    return result;
  }

  /**
   * Import Q-table from persistence
   */
  import(data: Record<string, { qValues: number[]; visits: number }>): void {
    this.qTable.clear();
    for (const [key, entry] of Object.entries(data)) {
      this.qTable.set(key, {
        qValues: new Float32Array(entry.qValues),
        visits: entry.visits,
        lastUpdate: Date.now(),
      });
    }
  }

  // Private methods

  /**
   * Legacy hash function (kept for backward compatibility)
   */
  private hashState(context: string): string {
    // Simple hash for context string
    let hash = 0;
    for (let i = 0; i < context.length; i++) {
      const char = context.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return `state_${hash}`;
  }

  /**
   * Public state-key encoder (#2239). This is exactly what `route()` uses
   * to look up Q-values, so testing it directly is testing the binding the
   * Q-learner actually sees.
   */
  getStateKey(context: string): string {
    return this.hashStateOptimized(context);
  }

  /**
   * Optimized state hashing using feature extraction
   * Creates a more semantic representation of the task context
   */
  private hashStateOptimized(context: string): string {
    // Check feature hash cache first
    if (this.featureHashCache.has(context)) {
      const cached = this.featureHashCache.get(context)!;
      return this.featureVectorToKey(cached);
    }

    // Extract features from context
    const features = this.extractFeatures(context);

    // Cache the feature vector
    if (this.featureHashCache.size < 1000) { // Limit cache size
      this.featureHashCache.set(context, features);
    }

    return this.featureVectorToKey(features);
  }

  /**
   * Extract feature vector from task context
   * Uses keyword matching and n-gram hashing
   */
  private extractFeatures(context: string): Float32Array {
    const features = new Float32Array(this.config.stateSpaceDim);
    const lowerContext = context.toLowerCase();
    const words = lowerContext.split(/\s+/);

    // Feature 1-32: Keyword presence (binary features)
    for (let i = 0; i < FEATURE_KEYWORDS.length && i < 32; i++) {
      if (lowerContext.includes(FEATURE_KEYWORDS[i])) {
        features[i] = 1.0;
      }
    }

    // Feature 33-40: Context length buckets
    const lengthBucket = Math.min(Math.floor(context.length / 50), 7);
    features[32 + lengthBucket] = 1.0;

    // Feature 41-48: Word count buckets
    const wordBucket = Math.min(Math.floor(words.length / 5), 7);
    features[40 + wordBucket] = 1.0;

    // Feature 49-56: File extension hints
    const extPatterns = ['.ts', '.js', '.py', '.go', '.rs', '.java', '.md', '.json'];
    for (let i = 0; i < extPatterns.length; i++) {
      if (lowerContext.includes(extPatterns[i])) {
        features[48 + i] = 1.0;
      }
    }

    // Feature 57-64: N-gram hash features (for capturing unique patterns)
    for (let i = 0; i < words.length - 1 && i < 8; i++) {
      const bigram = `${words[i]}_${words[i + 1]}`;
      const hash = this.murmurhash3(bigram) % 8;
      features[56 + hash] += 0.25;
    }

    // Normalize features
    let norm = 0;
    for (let i = 0; i < features.length; i++) {
      norm += features[i] * features[i];
    }
    norm = Math.sqrt(norm) || 1;
    for (let i = 0; i < features.length; i++) {
      features[i] /= norm;
    }

    return features;
  }

  /**
   * Convert feature vector to state key
   * Uses locality-sensitive hashing for similar contexts.
   *
   * #2239 — the previous fold was `((hash << 4) ^ q[i]) & 0x7fffffff` over 16
   * 4-bit groups: each group i landed at bit 4·(15−i), so groups 0–7 (= the
   * entire keyword block, features 0–31) shifted past the 31-bit mask and were
   * discarded. Keyword-distinct tasks collapsed to one Q-state. We now use a
   * 32-bit FNV-1a hash, which mixes every quantized group losslessly into the
   * state key. Encoder version bumped to 2; see PersistedModel.encoderVersion.
   */
  private featureVectorToKey(features: Float32Array): string {
    // Quantize features into 4-bit groups (16 groups for a 64-dim vector).
    const quantized: number[] = [];
    for (let i = 0; i < features.length; i += 4) {
      let bucket = 0;
      for (let j = 0; j < 4 && i + j < features.length; j++) {
        if (features[i + j] > 0.25) {
          bucket |= (1 << j);
        }
      }
      quantized.push(bucket);
    }

    // 32-bit FNV-1a over the quantized array — every group contributes.
    let hash = 0x811c9dc5 | 0; // FNV offset basis
    for (let i = 0; i < quantized.length; i++) {
      hash ^= quantized[i] & 0xff;
      hash = Math.imul(hash, 0x01000193); // FNV prime
    }
    return `fstate_${(hash >>> 0).toString(36)}`;
  }

  /**
   * MurmurHash3 32-bit implementation for n-gram hashing
   */
  private murmurhash3(str: string): number {
    let h1 = 0xdeadbeef;
    const c1 = 0xcc9e2d51;
    const c2 = 0x1b873593;

    for (let i = 0; i < str.length; i++) {
      let k1 = str.charCodeAt(i);
      k1 = Math.imul(k1, c1);
      k1 = (k1 << 15) | (k1 >>> 17);
      k1 = Math.imul(k1, c2);
      h1 ^= k1;
      h1 = (h1 << 13) | (h1 >>> 19);
      h1 = Math.imul(h1, 5) + 0xe6546b64;
    }

    h1 ^= str.length;
    h1 ^= h1 >>> 16;
    h1 = Math.imul(h1, 0x85ebca6b);
    h1 ^= h1 >>> 13;
    h1 = Math.imul(h1, 0xc2b2ae35);
    h1 ^= h1 >>> 16;

    return h1 >>> 0;
  }

  private getQValues(stateKey: string): number[] {
    const entry = this.qTable.get(stateKey);
    if (!entry) {
      return new Array(this.config.numActions).fill(0);
    }
    return Array.from(entry.qValues);
  }

  private getOrCreateEntry(stateKey: string): QEntry {
    let entry = this.qTable.get(stateKey);
    if (!entry) {
      entry = {
        qValues: new Float32Array(this.config.numActions),
        visits: 0,
        lastUpdate: Date.now(),
      };
      this.qTable.set(stateKey, entry);
    }
    return entry;
  }

  private argmax(values: number[]): number {
    let maxIdx = 0;
    let maxVal = values[0];
    for (let i = 1; i < values.length; i++) {
      if (values[i] > maxVal) {
        maxVal = values[i];
        maxIdx = i;
      }
    }
    return maxIdx;
  }

  private softmaxConfidence(qValues: number[], actionIdx: number): number {
    const maxQ = Math.max(...qValues);
    const expValues = qValues.map(q => Math.exp(q - maxQ)); // Subtract max for numerical stability
    const sumExp = expValues.reduce((a, b) => a + b, 0);
    return expValues[actionIdx] / sumExp;
  }

  private pruneQTable(): void {
    const entries = Array.from(this.qTable.entries())
      .sort((a, b) => a[1].lastUpdate - b[1].lastUpdate);

    const toRemove = entries.length - Math.floor(this.config.maxStates * 0.8);
    for (let i = 0; i < toRemove; i++) {
      this.qTable.delete(entries[i][0]);
    }
  }
}

/**
 * Factory function
 */
export function createQLearningRouter(config?: Partial<QLearningRouterConfig>): QLearningRouter {
  return new QLearningRouter(config);
}

/**
 * router-calibrator.ts — Post-hoc isotonic calibration for the KRR router
 * (ADR-149 iter 22).
 *
 * The bundled KRR systematically under-predicts at the low end (gap 0.45 at
 * 0.0–0.1) and over-predicts at the high end (gap 0.15 at 0.9–1.0). Both
 * deviations are monotone, so a piecewise-constant non-decreasing function
 * fit via Pool-Adjacent-Violators (PAV) can correct them without retraining
 * the KRR.
 *
 * USAGE
 *
 *   const cal = IsotonicCalibrator.fit([[0.07, 0.52], [0.55, 0.60], …]);
 *   const corrected = cal.transform(rawKrrScore);
 *
 *   // Persist & reload:
 *   writeFileSync(path, JSON.stringify(cal.toJSON()));
 *   const loaded = IsotonicCalibrator.fromJSON(JSON.parse(readFileSync(path, 'utf8')));
 *
 * Pure TS — no native deps. ~25 lines of fitting logic, O(n log n) sort +
 * O(n) PAV pass.
 *
 * @module router-calibrator
 */

export interface CalibratorBucket {
  /** Inclusive lower bound of predicted-values pooled into this bucket. */
  predMin: number;
  /** Inclusive upper bound. */
  predMax: number;
  /** Calibrated output value (mean of observed values in the pool). */
  calibrated: number;
  /** Number of (pred,obs) pairs pooled. */
  count: number;
}

export interface CalibratorJSON {
  v: 1;
  buckets: CalibratorBucket[];
}

export class IsotonicCalibrator {
  private buckets: CalibratorBucket[];

  private constructor(buckets: CalibratorBucket[]) {
    this.buckets = buckets;
  }

  /**
   * Fit an isotonic regression to (predicted, observed) pairs via PAV.
   *
   * Result is a non-decreasing piecewise-constant function over the
   * empirical predicted-value range, equivalent in spirit to sklearn's
   * IsotonicRegression(increasing=True, out_of_bounds='clip').
   */
  static fit(pairs: Array<[number, number]>): IsotonicCalibrator {
    if (pairs.length === 0) return new IsotonicCalibrator([]);
    // Sort by predicted value ascending; stable sort isn't required because
    // ties only affect bucket boundaries (which PAV then pools anyway).
    const sorted = [...pairs].sort((a, b) => a[0] - b[0]);

    type Pool = { predMin: number; predMax: number; sumObs: number; count: number };
    const pools: Pool[] = sorted.map(([p, o]) => ({ predMin: p, predMax: p, sumObs: o, count: 1 }));

    // Pool-Adjacent-Violators: walk left-to-right, merge adjacent pools
    // whose averages violate monotonicity. After merging, back up one step
    // to check the new pool against its predecessor.
    let i = 0;
    while (i < pools.length - 1) {
      const a = pools[i], b = pools[i + 1];
      const avgA = a.sumObs / a.count;
      const avgB = b.sumObs / b.count;
      if (avgA > avgB) {
        pools[i] = {
          predMin: a.predMin,
          predMax: b.predMax,
          sumObs: a.sumObs + b.sumObs,
          count: a.count + b.count,
        };
        pools.splice(i + 1, 1);
        if (i > 0) i--;
      } else {
        i++;
      }
    }

    const buckets: CalibratorBucket[] = pools.map(p => ({
      predMin: p.predMin,
      predMax: p.predMax,
      calibrated: p.sumObs / p.count,
      count: p.count,
    }));
    return new IsotonicCalibrator(buckets);
  }

  /**
   * Map a raw predicted value to its calibrated value. Uses piecewise-linear
   * interpolation between adjacent bucket midpoints, clamped at the
   * empirical edges (extrapolation outside the training range returns the
   * nearest edge bucket's calibrated value).
   */
  transform(x: number): number {
    const n = this.buckets.length;
    if (n === 0) return x;            // No calibration data → pass-through.
    if (n === 1) return this.buckets[0].calibrated;

    const mids = this.buckets.map(b => (b.predMin + b.predMax) / 2);
    if (x <= mids[0]) return this.buckets[0].calibrated;
    if (x >= mids[n - 1]) return this.buckets[n - 1].calibrated;

    // Linear interpolation between two adjacent bucket midpoints. Could be
    // binary-searched, but n is typically <30 after PAV so linear is fine.
    for (let i = 0; i < n - 1; i++) {
      if (x >= mids[i] && x <= mids[i + 1]) {
        const t = (x - mids[i]) / (mids[i + 1] - mids[i]);
        return this.buckets[i].calibrated * (1 - t) + this.buckets[i + 1].calibrated * t;
      }
    }
    return x; // unreachable given the bounds above
  }

  /** Pure-JSON serialization — calibrator JSON is small (typically <2kB). */
  toJSON(): CalibratorJSON {
    return { v: 1, buckets: this.buckets };
  }

  static fromJSON(j: CalibratorJSON): IsotonicCalibrator {
    if (!j || j.v !== 1) throw new Error(`unsupported calibrator schema v=${j?.v}`);
    return new IsotonicCalibrator(j.buckets);
  }

  /** Diagnostic — number of distinct calibration points after PAV. */
  get bucketCount(): number {
    return this.buckets.length;
  }

  /** Diagnostic — return a copy of the bucket array (read-only view). */
  inspect(): CalibratorBucket[] {
    return this.buckets.map(b => ({ ...b }));
  }
}

/**
 * router-parallel-recorder.ts — Opt-in SelfEvolvingRouter parallel-logging
 * recorder (ADR-150 Phase 2).
 *
 * Writes one JSON-line per PAIR of routing decisions (Thompson bandit pick
 * + SelfEvolvingRouter pick + measured outcome) to a shared
 * `.swarm/router-parallel.jsonl`. Designed to be matched by
 * `plugins/ruflo-metaharness/scripts/router-parallel-analyze.mjs` which
 * computes the 3-criteria AND-gate from ADR-150 review-round-1:
 *
 *   (a) qualityScore improvement > 2%
 *   (b) usdPerDecision increase   < 1%
 *   (c) p95 routing-decision latency increase < 5%
 *
 * ARCHITECTURAL CONSTRAINTS (ADR-150)
 * -----------------------------------
 * 1. REMOVABLE — `@metaharness/kernel` (which provides SelfEvolvingRouter)
 *    is in optionalDependencies. This module's exports are pure-shape; the
 *    `SerPick` carries pre-computed prediction fields. The caller is
 *    responsible for dynamic-importing the kernel and computing the SER
 *    pick — this module ONLY records the pair.
 * 2. OPTIONAL — every write goes through the `CLAUDE_FLOW_ROUTER_PARALLEL_LOG=1`
 *    env gate. When unset (default), `recordPair()` is a no-op.
 * 3. GRACEFUL DEGRADATION — every fs operation is try/caught at the
 *    appendFileSync boundary. A failed write logs to stderr (gated by
 *    DEBUG) but never throws — the routing decision continues.
 * 4. CI GATE — the analyzer + recorder are both exercised by smoke
 *    fixtures; no production data required for the contract to hold.
 *
 * SCHEMA (versioned, additive)
 * ----------------------------
 * One JSONL row per paired decision:
 *   {
 *     v: 1,
 *     ts: ISO-8601,
 *     task_hash: <FNV-1a-32 of task text>,
 *     task?: <truncated to 500 chars when CLAUDE_FLOW_ROUTER_PARALLEL_LOG_TASK=1>,
 *     bandit: { pick, predictedQuality, predictedCostUsd, ... },
 *     ser:    { pick, predictedQuality, predictedCostUsd, ... },
 *     outcome?: { actualModel, actualQuality, actualUsd, actualLatencyMs }
 *   }
 *
 * Outcomes can be filled in a separate `recordPairOutcome()` call (matched
 * by task_hash) so the routing path doesn't have to wait for execution.
 *
 * @module router-parallel-recorder
 */

import { appendFileSync, mkdirSync, existsSync, statSync, renameSync, unlinkSync } from 'node:fs';
import { dirname, join, resolve as resolvePath } from 'node:path';
import type { ClaudeModel } from './model-router.js';
import { taskHash } from './router-trajectory.js';

// ============================================================================
// Schema (versioned, additive)
// ============================================================================

/** Per-arm prediction for one routing decision. */
export interface ArmPick {
  pick: ClaudeModel;
  predictedQuality: number;        // 0..1 (model's own predicted quality on this task)
  predictedCostUsd: number;        // $/decision at the picked model
  /** Optional: backend identifier (bandit | metaharness-knn | metaharness-krr | self-evolving). */
  backend?: string;
}

/** Optional outcome — filled in after execution via recordPairOutcome(). */
export interface PairOutcome {
  /** Whichever model actually executed (typically the bandit's pick). */
  actualModel: ClaudeModel;
  /** Measured quality score from the verdict ladder (0..1). */
  actualQuality: number;
  /** Measured spend at actualModel's prices. */
  actualUsd: number;
  /** Wall-clock latency from route() to response complete (ms). */
  actualLatencyMs: number;
}

/** Discriminator for JSONL rows. */
export type RowType = 'pair' | 'pair-outcome';

/** One paired-decision row. */
export interface PairRow {
  v: 1;
  type: RowType;
  ts: string;
  task_hash: string;
  task?: string;                   // only present when explicit env opt-in
  bandit: ArmPick;
  ser: ArmPick;
  outcome?: PairOutcome;
}

// ============================================================================
// Config + rotation
// ============================================================================

interface RecorderConfig {
  enabled: boolean;
  path: string;
  /** Include the task text in rows (PII/retention concern; default off). */
  includeTaskText: boolean;
  /** Truncate task to this many chars when includeTaskText is on. */
  taskCharLimit: number;
  /** Rotate when file exceeds this size. */
  maxBytes: number;
}

let _cfg: RecorderConfig | null = null;

function getConfig(): RecorderConfig {
  if (_cfg !== null) return _cfg;
  _cfg = {
    enabled: process.env.CLAUDE_FLOW_ROUTER_PARALLEL_LOG === '1',
    path: process.env.CLAUDE_FLOW_ROUTER_PARALLEL_LOG_PATH
      ? resolvePath(process.env.CLAUDE_FLOW_ROUTER_PARALLEL_LOG_PATH)
      : resolvePath('.swarm', 'router-parallel.jsonl'),
    includeTaskText: process.env.CLAUDE_FLOW_ROUTER_PARALLEL_LOG_TASK === '1',
    taskCharLimit: parseInt(process.env.CLAUDE_FLOW_ROUTER_PARALLEL_LOG_TASK_LIMIT || '500', 10),
    maxBytes: parseInt(process.env.CLAUDE_FLOW_ROUTER_PARALLEL_LOG_MAX_BYTES || String(10 * 1024 * 1024), 10),
  };
  return _cfg;
}

function rotate(cfg: RecorderConfig): void {
  try {
    const backup = `${cfg.path}.1`;
    if (existsSync(backup)) unlinkSync(backup);
    renameSync(cfg.path, backup);
  } catch (e) {
    if (process.env.DEBUG) {
      // eslint-disable-next-line no-console
      console.error('router-parallel: rotate failed:', (e as Error).message);
    }
  }
}

function appendRow(row: PairRow): void {
  const cfg = getConfig();
  if (!cfg.enabled) return;
  try {
    const dir = dirname(cfg.path);
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    if (existsSync(cfg.path)) {
      try {
        const st = statSync(cfg.path);
        if (st.size >= cfg.maxBytes) rotate(cfg);
      } catch { /* stat race is fine */ }
    }
    appendFileSync(cfg.path, JSON.stringify(row) + '\n');
  } catch (e) {
    if (process.env.DEBUG) {
      // eslint-disable-next-line no-console
      console.error('router-parallel: appendRow failed:', (e as Error).message);
    }
    // ADR-150 rule #3 — never throw, never block the routing path.
  }
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Record one paired routing decision. Cheap — single appendFileSync of a
 * JSONL row. No-op when CLAUDE_FLOW_ROUTER_PARALLEL_LOG is unset (the
 * default). Never throws.
 *
 * The caller dynamic-imports `@metaharness/kernel` (or any alternative
 * predictor) and computes the SER pick BEFORE calling this. The recorder
 * deliberately knows nothing about how either pick was computed — it just
 * writes the pair.
 */
export function recordPair(args: {
  task: string;
  bandit: ArmPick;
  ser: ArmPick;
}): { recorded: boolean; taskHash: string } {
  const cfg = getConfig();
  const hash = taskHash(args.task);
  if (!cfg.enabled) return { recorded: false, taskHash: hash };

  const row: PairRow = {
    v: 1,
    type: 'pair',
    ts: new Date().toISOString(),
    task_hash: hash,
    bandit: args.bandit,
    ser: args.ser,
  };
  if (cfg.includeTaskText) {
    row.task = args.task.length > cfg.taskCharLimit
      ? args.task.slice(0, cfg.taskCharLimit) + '…'
      : args.task;
  }
  appendRow(row);
  return { recorded: true, taskHash: hash };
}

/**
 * Record the outcome of a previously-paired decision. Matched to its
 * pair row by task_hash. Writes a separate JSONL row of type 'outcome'
 * which the analyzer joins client-side (same pattern as the existing
 * router-trajectory recorder).
 *
 * Returns the task_hash that was matched (caller can verify against
 * what recordPair() returned).
 */
export function recordPairOutcome(args: {
  task: string;
  outcome: PairOutcome;
}): { recorded: boolean; taskHash: string } {
  const cfg = getConfig();
  const hash = taskHash(args.task);
  if (!cfg.enabled) return { recorded: false, taskHash: hash };
  const row: PairRow = {
    v: 1,
    type: 'pair-outcome',
    ts: new Date().toISOString(),
    task_hash: hash,
    bandit: { pick: args.outcome.actualModel, predictedQuality: 0, predictedCostUsd: 0 },
    ser: { pick: args.outcome.actualModel, predictedQuality: 0, predictedCostUsd: 0 },
    outcome: args.outcome,
  };
  appendRow(row);
  return { recorded: true, taskHash: hash };
}

/**
 * Status helper for diagnostics / smoke tests.
 */
export function parallelRecorderStatus(): {
  enabled: boolean;
  path: string;
  includeTaskText: boolean;
  taskCharLimit: number;
  maxBytes: number;
} {
  const cfg = getConfig();
  return {
    enabled: cfg.enabled,
    path: cfg.path,
    includeTaskText: cfg.includeTaskText,
    taskCharLimit: cfg.taskCharLimit,
    maxBytes: cfg.maxBytes,
  };
}

/** @internal — test helper. */
export function __resetParallelRecorderForTests(): void {
  _cfg = null;
}

/**
 * router-trajectory.ts — Opt-in DRACO-shaped trajectory recorder for the
 * cost-optimal model router (ADR-148, phase 5).
 *
 * Writes one JSON-line per routing decision and one per outcome to a
 * shared `.swarm/model-router-trajectories.jsonl`. Outcome rows are
 * matched to their decision via `task_hash` (FNV-1a-32 of the task text).
 *
 * Gated behind `CLAUDE_FLOW_ROUTER_TRAJECTORY=1`. Default: **off** — rows
 * carry full task text + raw embeddings, which is a PII/retention surface
 * we do not enable without explicit consent.
 *
 * Schema is versioned (`"v": 1`). New required fields bump the version;
 * additive optional fields do not.
 *
 * @module router-trajectory
 */

import { appendFileSync, mkdirSync, existsSync, statSync, renameSync, unlinkSync } from 'node:fs';
import { dirname, join, resolve as resolvePath } from 'node:path';

import type { ClaudeModel } from './model-router.js';
import type { NeuralRoutedBy } from './neural-router.js';
import { costUsd } from './model-prices.js';

// ============================================================================
// Schema (versioned)
// ============================================================================

/** A single routing decision — written at `route()` time. */
export interface TrajectoryDecisionRow {
  v: 1;
  type: 'decision';
  ts: string;                                  // ISO-8601, no millisecond ambiguity
  task_hash: string;                           // FNV-1a-32 hex of task text
  task: string;                                // ≤500 chars (truncated)
  embedding?: number[];                        // only present when supplied to route()
  complexity: number;                          // 0..1 from the heuristic features
  model: ClaudeModel;
  confidence: number;                          // 0..1
  uncertainty: number;                         // 0..1
  routed_by: 'hybrid' | 'bandit-fallback' | 'heuristic';
  /** Underlying neural backend when routed_by='hybrid', else absent. */
  neural_backend?: 'metaharness-knn' | 'metaharness-krr' | 'fastgrnn';
  /**
   * A/B mode (CLAUDE_FLOW_ROUTER_AB=1) attaches both the bandit-only pick
   * and the hybrid pick so disagreement rate is measurable over time.
   */
  ab_pair?: {
    bandit_pick: ClaudeModel;
    hybrid_pick: ClaudeModel;
    disagree: boolean;
  };
  /** Execution provider hint (phase 2): 'anthropic' or 'openrouter'. */
  provider?: 'anthropic' | 'openrouter';
  /** Concrete OpenRouter model slug when provider=openrouter. */
  openrouter_model?: string;
  /**
   * iter 46 — ensemble-disagreement diagnostic from iter 45. Absolute
   * difference between unified KRR and bucket specialist predictions for
   * the picked model. Set when both backends were queried (bucket
   * specialist available + bucket supplied). Persisting per-decision lets
   * a future tuner analyze the distribution and recommend an iter 44
   * threshold.
   */
  ensemble_disagreement?: number;
}

/** A routing outcome — written later by the caller via `recordOutcome()`. */
export interface TrajectoryOutcomeRow {
  v: 1;
  type: 'outcome';
  ts: string;
  task_hash: string;
  /** 0..1 measured quality the chosen model achieved. */
  quality: number;
  /** Optional per-model quality if the same query was evaluated against alternates. */
  scores?: Record<string, number>;
  /** Free-form provenance note (e.g. "manual rating", "benchmark suite"). */
  source?: string;
  /**
   * iter 31 — token usage from the underlying API response. Optional and
   * additive: pre-iter-31 readers see undefined; iter-31+ consumers can
   * sum these for production cost accounting. `modelId` is repeated here
   * (also in the paired decision row) so cost computation needs only the
   * outcome row — no JOIN required for streaming aggregation.
   */
  tokens?: { input: number; output: number };
  /** USD spend for this call. Computed at write time from `tokens` + the
   *  shared price table (model-prices.ts) so consumers get a canonical
   *  number even if prices change between write and read. */
  cost_usd?: number;
  /** Concrete model id the call dispatched against (iter 13+ wired this
   *  through agent.modelId). May differ from the bandit's tier label. */
  model_id?: string;
}

export type TrajectoryRow = TrajectoryDecisionRow | TrajectoryOutcomeRow;

// ============================================================================
// FNV-1a-32 (matches scripts/gen-seed-corpus.mjs)
// ============================================================================

export function taskHash(task: string): string {
  let h = 0x811c9dc5 >>> 0;
  for (let i = 0; i < task.length; i++) {
    h ^= task.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

// ============================================================================
// Recorder state
// ============================================================================

interface RecorderConfig {
  enabled: boolean;
  path: string;
  /** Max task chars to persist (default 500). */
  taskCharLimit: number;
  /** Max bytes before rotating (default 10 MB). 0 disables rotation. */
  maxSizeBytes: number;
  /** How many rotation backups to keep (default 3, named .1, .2, .3). */
  maxRotations: number;
}

let _cfg: RecorderConfig | null = null;
/** Cached size of the current file; updated incrementally on each append to
 *  avoid a `statSync` per write. -1 means "unknown, probe on next append". */
let _cachedSize = -1;

function getConfig(): RecorderConfig {
  if (_cfg !== null) return _cfg;
  const enabled = process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY === '1';
  const swarmDir = process.env.CLAUDE_FLOW_SWARM_DIR
    ?? resolvePath(process.cwd(), '.swarm');
  _cfg = {
    enabled,
    path: process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY_PATH
      ?? join(swarmDir, 'model-router-trajectories.jsonl'),
    taskCharLimit: parseInt(process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY_TASKLEN ?? '500', 10) || 500,
    maxSizeBytes: parseInt(process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY_MAXSIZE ?? `${10 * 1024 * 1024}`, 10) | 0,
    maxRotations: Math.max(0, parseInt(process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY_MAXROTATIONS ?? '3', 10) || 3),
  };
  return _cfg;
}

/** Rotate `path` → `path.1`, `path.1` → `path.2`, ..., dropping the oldest. */
function rotate(cfg: RecorderConfig): void {
  if (!existsSync(cfg.path)) return;
  try {
    // Walk from oldest to newest so each rename has a free target.
    if (cfg.maxRotations === 0) {
      // No history kept — just truncate by deleting.
      unlinkSync(cfg.path);
      return;
    }
    const oldest = `${cfg.path}.${cfg.maxRotations}`;
    if (existsSync(oldest)) unlinkSync(oldest);
    for (let i = cfg.maxRotations - 1; i >= 1; i--) {
      const src = `${cfg.path}.${i}`;
      if (existsSync(src)) renameSync(src, `${cfg.path}.${i + 1}`);
    }
    renameSync(cfg.path, `${cfg.path}.1`);
  } catch {
    // If rotation fails (permissions, race), drop back to overwriting the
    // active file by truncating its handle. Worst case we lose history.
    try { unlinkSync(cfg.path); } catch { /* */ }
  }
  _cachedSize = 0;
}

function appendRow(row: TrajectoryRow): void {
  const cfg = getConfig();
  if (!cfg.enabled) return;
  try {
    const dir = dirname(cfg.path);
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

    // Probe size lazily on first call this process, then track incrementally.
    if (_cachedSize < 0) {
      _cachedSize = existsSync(cfg.path) ? statSync(cfg.path).size : 0;
    }

    // One JSON object per line, newline-terminated. No leading whitespace —
    // we want the file to be `jq -c`-friendly.
    const line = JSON.stringify(row) + '\n';
    const bytes = Buffer.byteLength(line, 'utf8');

    // Rotate BEFORE writing if this row would push us past the cap.
    if (cfg.maxSizeBytes > 0 && _cachedSize + bytes > cfg.maxSizeBytes) {
      rotate(cfg);
    }

    appendFileSync(cfg.path, line);
    _cachedSize += bytes;
  } catch {
    // Silent: trajectory collection must never break routing.
  }
}

// ============================================================================
// Public API
// ============================================================================

/** Record one decision. Cheap — a single appendFileSync of a JSONL row. */
export function recordDecision(args: {
  task: string;
  embedding?: number[];
  complexity: number;
  model: ClaudeModel;
  confidence: number;
  uncertainty: number;
  routedBy: TrajectoryDecisionRow['routed_by'];
  neuralBackend?: TrajectoryDecisionRow['neural_backend'];
  abPair?: TrajectoryDecisionRow['ab_pair'];
  provider?: TrajectoryDecisionRow['provider'];
  openrouterModel?: TrajectoryDecisionRow['openrouter_model'];
  /** iter 46 — optional ensemble disagreement diagnostic (iter 45). */
  ensembleDisagreement?: number;
}): void {
  const cfg = getConfig();
  if (!cfg.enabled) return;
  const row: TrajectoryDecisionRow = {
    v: 1, type: 'decision',
    ts: new Date().toISOString(),
    task_hash: taskHash(args.task),
    task: args.task.length > cfg.taskCharLimit ? args.task.slice(0, cfg.taskCharLimit) : args.task,
    embedding: args.embedding,
    complexity: args.complexity,
    model: args.model,
    confidence: args.confidence,
    uncertainty: args.uncertainty,
    routed_by: args.routedBy,
    ...(args.neuralBackend ? { neural_backend: args.neuralBackend } : {}),
    ...(args.abPair ? { ab_pair: args.abPair } : {}),
    ...(args.provider ? { provider: args.provider } : {}),
    ...(args.openrouterModel ? { openrouter_model: args.openrouterModel } : {}),
    ...(args.ensembleDisagreement !== undefined ? { ensemble_disagreement: args.ensembleDisagreement } : {}),
  };
  appendRow(row);
}

/** Record one outcome. Join to a decision by `task_hash`. */
export function recordTrajectoryOutcome(args: {
  task: string;
  quality: number;
  scores?: Record<string, number>;
  source?: string;
  /** iter 31 — optional token usage from the underlying API call. */
  tokens?: { input: number; output: number };
  /** iter 31 — concrete model id for cost computation against MODEL_PRICES. */
  modelId?: string;
}): void {
  const cfg = getConfig();
  if (!cfg.enabled) return;
  // iter 31 — compute USD spend at write time using the canonical price
  // table. Cost is a first-class field so consumers don't need to JOIN
  // against the decision row (which may live in a rotated file).
  const cost_usd = args.tokens && (args.tokens.input > 0 || args.tokens.output > 0)
    ? costUsd(args.modelId, args.tokens.input, args.tokens.output)
    : undefined;
  const row: TrajectoryOutcomeRow = {
    v: 1, type: 'outcome',
    ts: new Date().toISOString(),
    task_hash: taskHash(args.task),
    quality: args.quality,
    scores: args.scores,
    source: args.source,
    ...(args.tokens ? { tokens: args.tokens } : {}),
    ...(cost_usd != null ? { cost_usd } : {}),
    ...(args.modelId ? { model_id: args.modelId } : {}),
  };
  appendRow(row);
}

/** Diagnostic for status/CLI. */
export function trajectoryRecorderStatus(): { enabled: boolean; path: string; taskCharLimit: number } {
  return { ...getConfig() };
}

// ============================================================================
// Trajectory → Training-row pairing (iter 18 — consumer side of iter 17)
// ============================================================================

/** A training row reconstructed from one decision+outcome pair. Shape matches
 *  the bundled seed-corpus (`seed-rows.json`) so the same train-bundled-krr.mjs
 *  pipeline can consume it. */
export interface PairedTrainingRow {
  task: string;
  embedding: number[];
  scores: Record<string, number>;
  tier: 'cheap' | 'mid' | 'strong';
  /** Provenance — useful for filtering low-signal sources at training time. */
  source: string;
  /** ISO timestamp of the outcome row (newer rows can be weighted higher). */
  ts: string;
}

/** Map decision-side complexity ∈ [0,1] back to the corpus tier label. The
 *  buckets are deliberately the same boundaries the bandit uses so a pair
 *  drawn from production lands in the same KRR specialist that served it. */
export function tierFromComplexity(complexity: number): 'cheap' | 'mid' | 'strong' {
  if (complexity < 0.34) return 'cheap';
  if (complexity < 0.67) return 'mid';
  return 'strong';
}

/** Pair decision+outcome rows by task_hash. Returns the rebuilt training rows
 *  + diagnostics so the caller (script or test) can report what was dropped
 *  and why. */
export function pairTrajectoryRows(
  rows: TrajectoryRow[],
): {
  pairs: PairedTrainingRow[];
  stats: {
    totalRows: number;
    decisions: number;
    outcomes: number;
    paired: number;
    droppedNoEmbedding: number;
    droppedNoMatch: number;
    bySource: Record<string, number>;
    byTier: Record<string, number>;
  };
} {
  const decisions = new Map<string, TrajectoryDecisionRow>();
  const outcomes = new Map<string, TrajectoryOutcomeRow>();

  // Latest-wins per hash. Production may re-run the same task — using the most
  // recent outcome avoids polluting the corpus with stale judgments.
  let dCount = 0, oCount = 0;
  for (const row of rows) {
    if (row.type === 'decision') {
      dCount++;
      const prev = decisions.get(row.task_hash);
      if (!prev || row.ts > prev.ts) decisions.set(row.task_hash, row);
    } else if (row.type === 'outcome') {
      oCount++;
      const prev = outcomes.get(row.task_hash);
      if (!prev || row.ts > prev.ts) outcomes.set(row.task_hash, row);
    }
  }

  const pairs: PairedTrainingRow[] = [];
  const bySource: Record<string, number> = {};
  const byTier: Record<string, number> = {};
  let droppedNoEmbedding = 0;
  let droppedNoMatch = 0;

  for (const [hash, dec] of decisions) {
    const out = outcomes.get(hash);
    if (!out) { droppedNoMatch++; continue; }
    if (!dec.embedding || dec.embedding.length === 0) { droppedNoEmbedding++; continue; }

    // scores map: prefer the outcome's full per-model map (set by callers who
    // ran multi-model comparisons); fall back to a single-model entry derived
    // from the model the decision actually dispatched.
    const scores: Record<string, number> = out.scores
      ?? { [dec.openrouter_model ?? dec.model]: out.quality };

    const tier = tierFromComplexity(dec.complexity);
    const source = out.source ?? 'unknown';

    pairs.push({
      task: dec.task,
      embedding: dec.embedding,
      scores,
      tier,
      source,
      ts: out.ts,
    });

    bySource[source] = (bySource[source] ?? 0) + 1;
    byTier[tier] = (byTier[tier] ?? 0) + 1;
  }

  return {
    pairs,
    stats: {
      totalRows: rows.length,
      decisions: dCount,
      outcomes: oCount,
      paired: pairs.length,
      droppedNoEmbedding,
      droppedNoMatch,
      bySource,
      byTier,
    },
  };
}

/** Test seam — reset cached config so unit tests can change env vars between cases. */
export function __resetTrajectoryRecorderForTests(): void {
  _cfg = null;
  _cachedSize = -1;
}

/**
 * RuVector LLM WASM Integration
 *
 * Wraps @ruvector/ruvllm-wasm for browser-native LLM inference utilities.
 * Provides HNSW routing, SONA instant adaptation, MicroLoRA fine-tuning,
 * chat template formatting, KV cache management, and inference arena.
 *
 * Published API (v2.0.2): RuvLLMWasm, ChatTemplateWasm, ChatMessageWasm,
 * GenerateConfig, HnswRouterWasm, SonaInstantWasm, MicroLoraWasm,
 * KvCacheWasm, BufferPoolWasm, InferenceArenaWasm.
 *
 * v2.0.2 fixes:
 * - HNSW supports 1000+ patterns (fixed connect_node ordering)
 * - MicroLoRA adapt() now takes (input: Float32Array, feedback: AdaptFeedbackWasm)
 *
 * Remaining quirks:
 * - Stats objects return WASM pointers — use .toJson() or named accessors
 * - GenerateConfig float precision loss (f32 roundtrip)
 * - MicroLoRA apply() hardcoded to 768 dims regardless of config
 *
 * @module @claude-flow/cli/ruvector/ruvllm-wasm
 */

import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';

// WASM binary requires at least 768-dim input for MicroLoRA adapt()
const MICROLORA_WASM_MIN_DIM = 768;

// ── Types ────────────────────────────────────────────────────

export interface HnswRouterConfig {
  dimensions: number;
  maxPatterns: number;
  efSearch?: number;
}

export interface HnswPattern {
  name: string;
  embedding: Float32Array;
  metadata?: Record<string, unknown>;
}

export interface HnswRouteResult {
  name: string;
  score: number;
  metadata?: Record<string, unknown>;
}

export interface SonaConfig {
  hiddenDim?: number;
  learningRate?: number;
  emaDecay?: number;
  ewcLambda?: number;
  microLoraRank?: number;
  patternCapacity?: number;
}

export interface MicroLoraConfig {
  inputDim: number;
  outputDim: number;
  rank?: number;
  alpha?: number;
}

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface GenerateOptions {
  maxTokens?: number;
  temperature?: number;
  topP?: number;
  topK?: number;
  repetitionPenalty?: number;
  stopSequences?: string[];
}

export interface RuvllmStatus {
  available: boolean;
  initialized: boolean;
  version: string | null;
}

// ── WASM Module Detection & Init ─────────────────────────────

let _wasmReady = false;

/**
 * Check if @ruvector/ruvllm-wasm is installed and loadable.
 */
export async function isRuvllmWasmAvailable(): Promise<boolean> {
  try {
    const mod = await import('@ruvector/ruvllm-wasm');
    return typeof mod.RuvLLMWasm === 'function';
  } catch {
    return false;
  }
}

/**
 * Initialize the WASM module for Node.js. Safe to call multiple times.
 * Uses initSync with object form: { module: bytes } (raw bytes deprecated).
 */
export async function initRuvllmWasm(): Promise<void> {
  if (_wasmReady) return;
  try {
    const mod = await import('@ruvector/ruvllm-wasm');
    const require_ = createRequire(import.meta.url);
    const wasmPath = require_.resolve('@ruvector/ruvllm-wasm/ruvllm_wasm_bg.wasm');
    const wasmBytes = readFileSync(wasmPath);
    // MUST use object form — initSync(bytes) is deprecated
    mod.initSync({ module: wasmBytes });
    _wasmReady = true;
  } catch (err) {
    throw new Error(`Failed to initialize @ruvector/ruvllm-wasm: ${err}`);
  }
}

/**
 * Get ruvllm-wasm status.
 */
export async function getRuvllmStatus(): Promise<RuvllmStatus> {
  const available = await isRuvllmWasmAvailable();
  if (!available) {
    return { available: false, initialized: false, version: null };
  }
  try {
    const mod = await import('@ruvector/ruvllm-wasm');
    // version is a standalone function, not on RuvLLMWasm class
    const version = typeof mod.getVersion === 'function' ? mod.getVersion() : null;
    return { available: true, initialized: _wasmReady, version };
  } catch {
    return { available: true, initialized: _wasmReady, version: null };
  }
}

// ── HNSW Router ──────────────────────────────────────────────

/**
 * Maximum safe pattern count for HNSW router.
 * v2.0.2 supports 1000+ patterns (fixed connect_node ordering).
 */
export const HNSW_MAX_SAFE_PATTERNS = 1024;

/**
 * Create a WASM HNSW router for semantic routing.
 * Returns an object with add/route/clear methods.
 *
 * Enforces HNSW_MAX_SAFE_PATTERNS limit (1024 in v2.0.2).
 */
export async function createHnswRouter(config: HnswRouterConfig): Promise<{
  addPattern: (pattern: HnswPattern) => boolean;
  route: (query: Float32Array, k?: number) => HnswRouteResult[];
  clear: () => void;
  patternCount: () => number;
  toJson: () => string;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const router = new mod.HnswRouterWasm(config.dimensions, config.maxPatterns);
  if (config.efSearch) {
    router.setEfSearch(config.efSearch);
  }

  let count = 0;

  return {
    addPattern(pattern: HnswPattern): boolean {
      if (count >= HNSW_MAX_SAFE_PATTERNS) {
        throw new Error(
          `HNSW pattern limit reached (${HNSW_MAX_SAFE_PATTERNS}).`
        );
      }
      const metadataJson = JSON.stringify(pattern.metadata ?? {});
      // addPattern requires 3 args: (embedding, name, metadata_json)
      const ok = router.addPattern(pattern.embedding, pattern.name, metadataJson);
      if (ok) count++;
      return ok;
    },
    route(query: Float32Array, k = 3): HnswRouteResult[] {
      const raw = router.route(query, k);
      return Array.from(raw).map((r: any) => ({
        name: r.name ?? r.pattern_name ?? '',
        score: r.score ?? r.distance ?? 0,
        metadata: r.metadata ? (typeof r.metadata === 'string' ? JSON.parse(r.metadata) : r.metadata) : undefined,
      }));
    },
    clear(): void {
      router.clear();
      count = 0;
    },
    patternCount(): number {
      return count;
    },
    toJson(): string {
      return router.toJson();
    },
  };
}

// ── SONA Instant Adaptation ──────────────────────────────────

/**
 * Create a SONA instant adaptation loop (<1ms adaptation).
 * v2.0.1: requires SonaConfigWasm object, not raw number.
 */
export async function createSonaInstant(config: SonaConfig = {}): Promise<{
  adapt: (quality: number) => void;
  recordPattern: (embedding: number[], success: boolean) => void;
  suggestAction: (context: string) => string | undefined;
  stats: () => string;
  reset: () => void;
  toJson: () => string;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const sonaConfig = new mod.SonaConfigWasm();
  if (config.hiddenDim !== undefined) sonaConfig.hiddenDim = config.hiddenDim;
  if (config.learningRate !== undefined) sonaConfig.learningRate = config.learningRate;
  if (config.emaDecay !== undefined) sonaConfig.emaDecay = config.emaDecay;
  if (config.ewcLambda !== undefined) sonaConfig.ewcLambda = config.ewcLambda;
  if (config.microLoraRank !== undefined) sonaConfig.microLoraRank = config.microLoraRank;
  if (config.patternCapacity !== undefined) sonaConfig.patternCapacity = config.patternCapacity;

  const sona = new mod.SonaInstantWasm(sonaConfig);

  return {
    adapt(quality: number): void {
      sona.instantAdapt(quality);
    },
    recordPattern(embedding: number[], success: boolean): void {
      sona.recordPattern(embedding, success);
    },
    suggestAction(context: string): string | undefined {
      return sona.suggestAction(context);
    },
    stats(): string {
      return sona.toJson();
    },
    reset(): void {
      sona.reset();
    },
    toJson(): string {
      return sona.toJson();
    },
  };
}

// ── MicroLoRA ────────────────────────────────────────────────

/**
 * Create a MicroLoRA adapter (ultra-lightweight LoRA, ranks 1-4).
 * v2.0.2: .adapt(input, feedback) takes Float32Array + AdaptFeedbackWasm.
 */
export async function createMicroLora(config: MicroLoraConfig): Promise<{
  apply: (input: Float32Array) => Float32Array;
  adapt: (quality: number, learningRate?: number, success?: boolean) => void;
  applyUpdates: (learningRate?: number) => void;
  stats: () => string;
  reset: () => void;
  toJson: () => string;
  pendingUpdates: () => number;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const loraConfig = new mod.MicroLoraConfigWasm();
  loraConfig.inputDim = config.inputDim;
  loraConfig.outputDim = config.outputDim;
  loraConfig.rank = config.rank ?? 2;
  loraConfig.alpha = config.alpha ?? 1.0;

  const lora = new mod.MicroLoraWasm(loraConfig);

  return {
    apply(input: Float32Array): Float32Array {
      return lora.apply(input);
    },
    adapt(quality: number, learningRate = 0.01, success = true): void {
      const feedback = new mod.AdaptFeedbackWasm();
      feedback.quality = quality;
      feedback.learningRate = learningRate;
      try { (feedback as any).success = success; } catch { /* v2.0.2 quirk */ }
      const input = new Float32Array(Math.max(config.inputDim, MICROLORA_WASM_MIN_DIM));
      lora.adapt(input, feedback);
      // Flush accumulated gradients. HONEST CAVEAT (audit
      // docs/reviews/intelligence-system-audit-2026-05-29.md): even WITH this
      // flush, the shipped @ruvector/ruvllm-wasm@2.0.2 MicroLoraWasm.apply()
      // output is empirically UNCHANGED (measured maxAbsDelta = 0 after 200
      // adapts). MicroLoRA adaptation is therefore effectively a no-op on
      // inference with this WASM backend. We do NOT synthesize a fake gradient
      // from the scalar quality to make output "move" — that would be a
      // fabricated signal. Real adaptation needs the WASM backend to flush B,
      // or a caller supplying real gradients.
      lora.applyUpdates(learningRate as unknown as Float32Array);
    },
    applyUpdates(learningRate = 0.01): void {
      // WASM runtime signature is applyUpdates(learning_rate: number); the
      // shipped .d.ts mistypes it as Float32Array, hence the cast.
      lora.applyUpdates(learningRate as unknown as Float32Array);
    },
    stats(): string {
      return lora.toJson();
    },
    reset(): void {
      lora.reset();
    },
    toJson(): string {
      return lora.toJson();
    },
    pendingUpdates(): number {
      return lora.pendingUpdates();
    },
  };
}

// ── Chat Template Formatting ─────────────────────────────────

type TemplatePreset = 'llama3' | 'mistral' | 'chatml' | 'phi' | 'gemma';

/**
 * Format chat messages using a chat template.
 * Supports presets (llama3, mistral, chatml, phi, gemma) and auto-detection.
 */
export async function formatChat(
  messages: ChatMessage[],
  template: TemplatePreset | { custom: string } | { modelId: string },
): Promise<string> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  // Build template
  let tmpl: any;
  if (typeof template === 'string') {
    const presets: Record<string, () => any> = {
      llama3: () => mod.ChatTemplateWasm.llama3(),
      mistral: () => mod.ChatTemplateWasm.mistral(),
      chatml: () => mod.ChatTemplateWasm.chatml(),
      phi: () => mod.ChatTemplateWasm.phi(),
      gemma: () => mod.ChatTemplateWasm.gemma(),
    };
    const factory = presets[template];
    if (!factory) throw new Error(`Unknown template preset: ${template}. Use: ${Object.keys(presets).join(', ')}`);
    tmpl = factory();
  } else if ('custom' in template) {
    tmpl = mod.ChatTemplateWasm.custom(template.custom);
  } else if ('modelId' in template) {
    tmpl = mod.ChatTemplateWasm.detectFromModelId(template.modelId);
  }

  // Build messages
  const wasmMessages = messages.map(m => {
    switch (m.role) {
      case 'system': return mod.ChatMessageWasm.system(m.content);
      case 'user': return mod.ChatMessageWasm.user(m.content);
      case 'assistant': return mod.ChatMessageWasm.assistant(m.content);
      default: throw new Error(`Unknown role: ${m.role}`);
    }
  });

  return tmpl.format(wasmMessages);
}

