/**
 * Pure JavaScript SemanticRouter implementation
 *
 * Provides intent routing using cosine similarity.
 * This is a fallback implementation since @ruvector/router's native VectorDb has bugs.
 *
 * Performance: ~50,000 routes/sec with 100 intents (sufficient for agent routing)
 */

export interface Intent {
  name: string;
  utterances: string[];
  metadata?: Record<string, unknown>;
}

export interface RouteResult {
  intent: string;
  score: number;
  metadata: Record<string, unknown>;
}

export interface RouterConfig {
  dimension: number;
  metric?: 'cosine' | 'euclidean' | 'dotProduct';
}

interface StoredIntent {
  name: string;
  embeddings: Float32Array[];
  metadata: Record<string, unknown>;
}

export class SemanticRouter {
  private dimension: number;
  private metric: 'cosine' | 'euclidean' | 'dotProduct';
  private intents: Map<string, StoredIntent> = new Map();
  private totalVectors = 0;

  constructor(config: RouterConfig) {
    if (!config || typeof config.dimension !== 'number') {
      throw new Error('SemanticRouter requires a dimension in config');
    }
    this.dimension = config.dimension;
    this.metric = config.metric ?? 'cosine';
  }

  /**
   * Add an intent with pre-computed embeddings
   */
  addIntentWithEmbeddings(
    name: string,
    embeddings: Float32Array[],
    metadata: Record<string, unknown> = {}
  ): void {
    if (!name || !Array.isArray(embeddings)) {
      throw new Error('Must provide name and embeddings array');
    }

    // Validate embeddings
    for (const emb of embeddings) {
      if (!(emb instanceof Float32Array) || emb.length !== this.dimension) {
        throw new Error(`Embedding must be Float32Array of length ${this.dimension}`);
      }
    }

    // Normalize embeddings for cosine similarity
    const normalizedEmbeddings = embeddings.map(emb => this.normalize(emb));

    this.intents.set(name, {
      name,
      embeddings: normalizedEmbeddings,
      metadata,
    });
    this.totalVectors += embeddings.length;
  }

  /**
   * Route a query using a pre-computed embedding
   */
  routeWithEmbedding(embedding: Float32Array, k = 5): RouteResult[] {
    if (!(embedding instanceof Float32Array) || embedding.length !== this.dimension) {
      throw new Error(`Embedding must be Float32Array of length ${this.dimension}`);
    }

    const normalizedQuery = this.normalize(embedding);
    const scores: { intent: string; score: number; metadata: Record<string, unknown> }[] = [];

    // Calculate best score for each intent
    for (const [intentName, intent] of this.intents) {
      let bestScore = -Infinity;

      for (const storedEmb of intent.embeddings) {
        const score = this.similarity(normalizedQuery, storedEmb);
        if (score > bestScore) {
          bestScore = score;
        }
      }

      scores.push({
        intent: intentName,
        score: bestScore,
        metadata: intent.metadata,
      });
    }

    // Sort by score descending and take top k
    return scores
      .sort((a, b) => b.score - a.score)
      .slice(0, k);
  }

  /**
   * Remove an intent
   */
  removeIntent(name: string): boolean {
    const intent = this.intents.get(name);
    if (!intent) return false;

    this.totalVectors -= intent.embeddings.length;
    this.intents.delete(name);
    return true;
  }

  /**
   * Get all intent names
   */
  getIntents(): string[] {
    return Array.from(this.intents.keys());
  }

  /**
   * Get intent details
   */
  getIntent(name: string): Intent | null {
    const data = this.intents.get(name);
    if (!data) return null;
    return {
      name: data.name,
      utterances: [], // We don't store utterances, only embeddings
      metadata: data.metadata,
    };
  }

  /**
   * Clear all intents
   */
  clear(): void {
    this.intents.clear();
    this.totalVectors = 0;
  }

  /**
   * Get total vector count
   */
  count(): number {
    return this.totalVectors;
  }

  /**
   * Get number of intents
   */
  intentCount(): number {
    return this.intents.size;
  }

  /**
   * Normalize a vector for cosine similarity
   */
  private normalize(vec: Float32Array): Float32Array {
    let norm = 0;
    for (let i = 0; i < vec.length; i++) {
      norm += vec[i] * vec[i];
    }
    norm = Math.sqrt(norm);

    if (norm === 0) return vec;

    const normalized = new Float32Array(vec.length);
    for (let i = 0; i < vec.length; i++) {
      normalized[i] = vec[i] / norm;
    }
    return normalized;
  }

  /**
   * Calculate similarity between two normalized vectors
   */
  private similarity(a: Float32Array, b: Float32Array): number {
    switch (this.metric) {
      case 'cosine':
        // For normalized vectors, cosine similarity = dot product
        return this.dotProduct(a, b);
      case 'dotProduct':
        return this.dotProduct(a, b);
      case 'euclidean':
        // Convert Euclidean distance to similarity
        return 1 / (1 + this.euclideanDistance(a, b));
      default:
        return this.dotProduct(a, b);
    }
  }

  private dotProduct(a: Float32Array, b: Float32Array): number {
    let sum = 0;
    for (let i = 0; i < a.length; i++) {
      sum += a[i] * b[i];
    }
    return sum;
  }

  private euclideanDistance(a: Float32Array, b: Float32Array): number {
    let sum = 0;
    for (let i = 0; i < a.length; i++) {
      const diff = a[i] - b[i];
      sum += diff * diff;
    }
    return Math.sqrt(sum);
  }
}

/**
 * Create a SemanticRouter with the given configuration
 */
export function createSemanticRouter(config: RouterConfig): SemanticRouter {
  return new SemanticRouter(config);
}

export default SemanticRouter;

/**
 * task-embedder.ts — Shared lazy task embedder + LRU cache (ADR-149 iter 9).
 *
 * The cost-optimal neural router (ADR-149) fires only when `route(task, embedding)`
 * is called with a real embedding. Two call sites in the dispatcher chain need
 * embeddings: `agent-tools.ts` (initial routing) and `agent-execute-core.ts`
 * (the fallback chain on 429/5xx). Before this module they each loaded their
 * own @xenova/transformers MiniLM pipeline and recomputed embeddings on every
 * call — including for repeated prompts.
 *
 * This module:
 *   1. Loads the pipeline once per process (`loadTaskEmbedder`).
 *   2. Caches embeddings per task text via an LRU of configurable size
 *      (default 500 entries ≈ 1.5 MB at 384-dim).
 *   3. Hashes by FNV-1a-32 + length to keep the key compact and collision-safe
 *      for typical prompt sizes.
 *   4. Returns `undefined` on any failure so callers gracefully fall back to
 *      the heuristic+bandit path.
 *
 * @module task-embedder
 */

// ============================================================================
// FNV-1a-32 hash (matches scripts/gen-seed-corpus.mjs + router-trajectory.ts)
// ============================================================================

function fnv1a32(s: string): string {
  let h = 0x811c9dc5 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

/** Compact cache key — hash + length so distinct prompts of similar shape collide rarely. */
function cacheKey(task: string): string {
  return `${fnv1a32(task)}:${task.length}`;
}

// ============================================================================
// Lazy pipeline load (shared across all callers in the process)
// ============================================================================

type EmbedFn = (text: string) => Promise<number[]>;
type EmbedBatchFn = (texts: string[]) => Promise<number[][]>;
type ExtractorFn = (input: string | string[], opts: { pooling: 'mean'; normalize: boolean }) =>
  Promise<{ data: Float32Array; dims?: number[] }>;

// Single shared extractor. Both single-text and array-input modes call this
// same function (xenova's pipeline returns a callable that accepts either),
// so we don't pay the ONNX model-load cost twice.
let _extractorPromise: Promise<ExtractorFn | null> | null = null;

function loadExtractor(): Promise<ExtractorFn | null> {
  if (_extractorPromise !== null) return _extractorPromise;
  _extractorPromise = (async () => {
    try {
      const specifier = '@xenova/transformers';
      const mod = await import(/* @vite-ignore */ specifier).catch(() => null);
      if (!mod || typeof mod.pipeline !== 'function') return null;
      return await mod.pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2', { quantized: true });
    } catch {
      return null;
    }
  })();
  return _extractorPromise;
}

async function loadEmbedder(): Promise<EmbedFn | null> {
  const ex = await loadExtractor();
  if (!ex) return null;
  return async (text: string): Promise<number[]> => {
    const out = await ex(text, { pooling: 'mean', normalize: true });
    return Array.from(out.data as Float32Array);
  };
}

/**
 * Array-input batch embedder — xenova's pipeline accepts `string[]` and
 * returns a stacked tensor of shape `[N, dim]`. Shares the same loaded
 * pipeline with `loadEmbedder` so cold-load cost is paid once across
 * single + batch usage. Measured speedup: ~1.83× on 30-task batches
 * against the same-pipeline single-call loop.
 */
async function loadEmbedderBatch(): Promise<EmbedBatchFn | null> {
  const ex = await loadExtractor();
  if (!ex) return null;
  return async (texts: string[]): Promise<number[][]> => {
    const out = await ex(texts, { pooling: 'mean', normalize: true });
    const dims = out.dims ?? [texts.length, 384];
    const N = dims[0] ?? texts.length;
    const dim = dims[1] ?? Math.floor(out.data.length / N);
    const data = out.data;
    const result: number[][] = new Array(N);
    for (let i = 0; i < N; i++) {
      result[i] = Array.from(data.subarray(i * dim, (i + 1) * dim));
    }
    return result;
  };
}

// ============================================================================
// LRU cache — Map preserves insertion order, so delete+set on hit = O(1) LRU
// ============================================================================

const MAX_SIZE = (() => {
  const v = parseInt(process.env.CLAUDE_FLOW_ROUTER_EMBED_CACHE_SIZE ?? '500', 10);
  return Number.isFinite(v) && v >= 0 ? v : 500;
})();

const _cache: Map<string, number[]> = new Map();
let _hits = 0;
let _misses = 0;

function lruGet(key: string): number[] | undefined {
  const hit = _cache.get(key);
  if (hit === undefined) return undefined;
  // Refresh recency: re-insert at the end.
  _cache.delete(key);
  _cache.set(key, hit);
  return hit;
}

function lruSet(key: string, value: number[]): void {
  if (MAX_SIZE === 0) return;
  if (_cache.has(key)) _cache.delete(key);
  _cache.set(key, value);
  while (_cache.size > MAX_SIZE) {
    const oldest = _cache.keys().next().value;
    if (oldest === undefined) break;
    _cache.delete(oldest);
  }
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Compute (or fetch from cache) the 384-dim MiniLM embedding for `task`.
 * Returns `undefined` on any failure (missing @xenova/transformers, ONNX
 * runtime error, etc.) so callers can gracefully fall back to the
 * heuristic+bandit path. Best-effort and never throws.
 *
 * Cache hit-rate accumulates across the process lifetime and is observable
 * via `embedderStats()` for diagnostics.
 */
export async function embedTaskWithCache(task: string): Promise<number[] | undefined> {
  if (typeof task !== 'string' || task.length === 0) return undefined;
  const key = cacheKey(task);
  const cached = lruGet(key);
  if (cached !== undefined) {
    _hits++;
    return cached;
  }
  try {
    const embed = await loadEmbedder();
    if (!embed) return undefined;
    const v = await embed(task);
    lruSet(key, v);
    _misses++;
    return v;
  } catch {
    return undefined;
  }
}

/**
 * Batch counterpart to `embedTaskWithCache`. For each task, returns the
 * cached embedding when present, else schedules a fresh inference. The
 * fresh-inference set is computed in a SINGLE ONNX pass via
 * @xenova/transformers' array-input mode, amortizing tensor setup +
 * model-load overhead across the batch. Order of the output array
 * matches the input order.
 *
 * Returns `undefined` for any task that failed to embed (missing dep,
 * runtime error). Cache state updates as if each task had been called
 * separately through embedTaskWithCache (hits/misses counters update
 * accordingly).
 */
export async function embedTaskWithCacheBatch(tasks: string[]): Promise<Array<number[] | undefined>> {
  const out: Array<number[] | undefined> = new Array(tasks.length).fill(undefined);
  // Validate + split into (cached-hits) and (missing-needs-inference).
  const missingIdx: number[] = [];
  const missingTasks: string[] = [];
  const missingKeys: string[] = [];
  for (let i = 0; i < tasks.length; i++) {
    const t = tasks[i];
    if (typeof t !== 'string' || t.length === 0) continue;
    const key = cacheKey(t);
    const hit = lruGet(key);
    if (hit !== undefined) {
      _hits++;
      out[i] = hit;
    } else {
      missingIdx.push(i);
      missingTasks.push(t);
      missingKeys.push(key);
    }
  }
  if (missingTasks.length === 0) return out;
  try {
    const embedBatch = await loadEmbedderBatch();
    if (!embedBatch) {
      for (let j = 0; j < missingIdx.length; j++) _misses++;
      return out;
    }
    // Real array-input batch: xenova returns one stacked tensor we slice
    // back into N embeddings. Amortizes tensor setup + ONNX overhead
    // across the batch (measured 1.83× speedup at N=30).
    const fresh = await embedBatch(missingTasks);
    for (let j = 0; j < missingIdx.length; j++) {
      const v = fresh[j];
      if (v) {
        lruSet(missingKeys[j], v);
        out[missingIdx[j]] = v;
      }
      _misses++;
    }
  } catch {
    // best-effort — leave undefined entries as is
  }
  return out;
}

/** Diagnostic surface — hit/miss counters + cache state. */
export function embedderStats(): { size: number; maxSize: number; hits: number; misses: number; hitRate: number } {
  const total = _hits + _misses;
  return {
    size: _cache.size,
    maxSize: MAX_SIZE,
    hits: _hits,
    misses: _misses,
    hitRate: total > 0 ? _hits / total : 0,
  };
}

/** Test seam — clear LRU + counters so tests get a fresh baseline. */
export function __resetTaskEmbedderForTests(): void {
  _cache.clear();
  _hits = 0;
  _misses = 0;
  _extractorPromise = null;
}

/**
 * trajectory-tree.ts — Execution-state-tree retrieval PROTOTYPE (MAGE-style).
 *
 * Research basis: MAGE (arXiv 2606.06090) observes that semantic-similarity
 * retrieval fragments decision trajectories on long-horizon tasks; retrieving
 * by POSITION in a hierarchical execution-state tree (the root→current path)
 * preserves coherence. This module mirrors ruflo's existing trajectory
 * recording (hooks_intelligence_trajectory-start/step/end) into such a tree
 * and offers position-based recall — NO embedding search anywhere.
 *
 * Structure:
 *   session root ─ trajectory ─ step
 *                       └ trajectory (nested: a start while another is open
 *                                     opens UNDER the open one) ─ step …
 *
 * - `trajectory-start` opens a node under the deepest open trajectory of the
 *   session (or the session root).
 * - `trajectory-step` appends a step child; the step becomes the "current"
 *   position of the session.
 * - `trajectory-end` closes the node; current returns to its parent.
 * - `recallPath({sessionId, depth})` returns the root→current path (the
 *   MAGE-style working context) plus the most recent siblings of the current
 *   node.
 *
 * PROTOTYPE LIMITATIONS (deliberate — see the feature spec):
 * - Persistence is a single best-effort JSON snapshot at
 *   `.claude-flow/intelligence/trajectory-tree.json`, written on every
 *   mutation. It sits ALONGSIDE the existing 'trajectories' memory-namespace
 *   persistence; nothing is migrated and the semantic path is untouched.
 * - No concurrency control: two MCP server processes sharing a cwd will
 *   last-writer-win the snapshot.
 * - No pruning/compaction: long-lived sessions grow the file unboundedly
 *   (labels are truncated to 200 chars to bound row size, not row count).
 * - sessionId defaults to CLAUDE_FLOW_SESSION_ID or 'default'; hosts that
 *   never set it collapse into one tree.
 * - Retrieval is position-only by design; hybrid position+semantic ranking
 *   is future work.
 *
 * @module ruvector/trajectory-tree
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

export type TreeNodeKind = 'session' | 'trajectory' | 'step';

export interface TreeNode {
  id: string;
  kind: TreeNodeKind;
  /** Task text (trajectory), action text (step), or session id — ≤200 chars. */
  label: string;
  parentId: string | null;
  childIds: string[];
  status: 'open' | 'closed';
  openedAt: string;
  closedAt?: string;
  meta?: Record<string, unknown>;
}

export interface RecallResult {
  sessionId: string;
  /** Root→current node path (the MAGE-style working context). */
  path: TreeNode[];
  /** Most recent siblings of the current node (excluding it), oldest→newest. */
  siblings: TreeNode[];
  /** Id of the current node (deepest position in the session). */
  currentId: string | null;
  strategy: 'state-tree';
}

interface TreeSnapshot {
  v: 1;
  nodes: Record<string, TreeNode>;
  currentBySession: Record<string, string>;
  trajectorySession: Record<string, string>;
}

const DEFAULT_PERSIST_PATH = join('.claude-flow', 'intelligence', 'trajectory-tree.json');
const LABEL_MAX = 200;

function now(): string {
  return new Date().toISOString();
}

function truncate(text: string): string {
  return text.length > LABEL_MAX ? `${text.slice(0, LABEL_MAX - 1)}…` : text;
}

export class TrajectoryTree {
  private nodes = new Map<string, TreeNode>();
  /** sessionId → id of the deepest "current" node (step or open trajectory). */
  private currentBySession = new Map<string, string>();
  /** trajectoryId → sessionId, so step/end calls can omit the session. */
  private trajectorySession = new Map<string, string>();
  private readonly persistPath: string;

  constructor(persistPath?: string) {
    this.persistPath = resolve(persistPath ?? DEFAULT_PERSIST_PATH);
    this.load();
  }

  private sessionRootId(sessionId: string): string {
    return `session:${sessionId}`;
  }

  private ensureSession(sessionId: string): TreeNode {
    const id = this.sessionRootId(sessionId);
    let node = this.nodes.get(id);
    if (!node) {
      node = {
        id,
        kind: 'session',
        label: truncate(sessionId),
        parentId: null,
        childIds: [],
        status: 'open',
        openedAt: now(),
      };
      this.nodes.set(id, node);
    }
    return node;
  }

  /** Deepest OPEN trajectory node on the current path of a session, if any. */
  private deepestOpenTrajectory(sessionId: string): TreeNode | null {
    let cursor = this.nodes.get(this.currentBySession.get(sessionId) ?? '');
    while (cursor) {
      if (cursor.kind === 'trajectory' && cursor.status === 'open') return cursor;
      cursor = cursor.parentId ? this.nodes.get(cursor.parentId) : undefined;
    }
    return null;
  }

  openTrajectory(args: { sessionId: string; trajectoryId: string; task: string; agent?: string }): TreeNode {
    const session = this.ensureSession(args.sessionId);
    const parent = this.deepestOpenTrajectory(args.sessionId) ?? session;
    const node: TreeNode = {
      id: args.trajectoryId,
      kind: 'trajectory',
      label: truncate(args.task),
      parentId: parent.id,
      childIds: [],
      status: 'open',
      openedAt: now(),
      meta: args.agent ? { agent: args.agent } : undefined,
    };
    this.nodes.set(node.id, node);
    parent.childIds.push(node.id);
    this.trajectorySession.set(args.trajectoryId, args.sessionId);
    this.currentBySession.set(args.sessionId, node.id);
    this.save();
    return node;
  }

  appendStep(args: { trajectoryId: string; stepId: string; action: string; quality?: number }): TreeNode | null {
    const trajectory = this.nodes.get(args.trajectoryId);
    if (!trajectory || trajectory.kind !== 'trajectory') return null;
    const sessionId = this.trajectorySession.get(args.trajectoryId);
    // The upstream stepId scheme (`step-${Date.now()}`) can collide within a
    // millisecond — uniquify locally instead of clobbering an existing node.
    let stepId = args.stepId;
    let bump = 1;
    while (this.nodes.has(stepId)) stepId = `${args.stepId}-${bump++}`;
    const node: TreeNode = {
      id: stepId,
      kind: 'step',
      label: truncate(args.action),
      parentId: trajectory.id,
      childIds: [],
      status: 'closed',
      openedAt: now(),
      closedAt: now(),
      meta: args.quality !== undefined ? { quality: args.quality } : undefined,
    };
    this.nodes.set(node.id, node);
    trajectory.childIds.push(node.id);
    if (sessionId) this.currentBySession.set(sessionId, node.id);
    this.save();
    return node;
  }

  closeTrajectory(args: { trajectoryId: string; success?: boolean }): TreeNode | null {
    const trajectory = this.nodes.get(args.trajectoryId);
    if (!trajectory || trajectory.kind !== 'trajectory') return null;
    trajectory.status = 'closed';
    trajectory.closedAt = now();
    if (args.success !== undefined) {
      trajectory.meta = { ...trajectory.meta, success: args.success };
    }
    const sessionId = this.trajectorySession.get(args.trajectoryId);
    if (sessionId && trajectory.parentId) {
      // Current position pops back to the enclosing trajectory / session root.
      this.currentBySession.set(sessionId, trajectory.parentId);
    }
    this.save();
    return trajectory;
  }

  /**
   * MAGE-style positional recall: the exact root→current path for a session,
   * plus the most recent siblings of the current node for local context.
   *
   * @param depth Max number of path nodes returned, counted from the CURRENT
   *              node upward (deepest levels win). Default: full path.
   * @param siblingWindow Max recent siblings of the current node. Default 3.
   */
  recallPath(args: { sessionId: string; depth?: number; siblingWindow?: number }): RecallResult {
    const currentId = this.currentBySession.get(args.sessionId) ?? null;
    const path: TreeNode[] = [];
    let cursor = currentId ? this.nodes.get(currentId) : undefined;
    while (cursor) {
      path.unshift(cursor);
      cursor = cursor.parentId ? this.nodes.get(cursor.parentId) : undefined;
    }
    const depth = args.depth && args.depth > 0 ? args.depth : path.length;
    const trimmedPath = path.slice(Math.max(0, path.length - depth));

    const siblingWindow = args.siblingWindow ?? 3;
    let siblings: TreeNode[] = [];
    const current = currentId ? this.nodes.get(currentId) : undefined;
    const parent = current?.parentId ? this.nodes.get(current.parentId) : undefined;
    if (current && parent) {
      siblings = parent.childIds
        .filter(id => id !== current.id)
        .map(id => this.nodes.get(id))
        .filter((n): n is TreeNode => !!n)
        .slice(-siblingWindow);
    }

    return { sessionId: args.sessionId, path: trimmedPath, siblings, currentId, strategy: 'state-tree' };
  }

  get size(): number {
    return this.nodes.size;
  }

  // ── Persistence (best-effort JSON snapshot) ──────────────────────────────

  private load(): void {
    try {
      if (!existsSync(this.persistPath)) return;
      const raw = JSON.parse(readFileSync(this.persistPath, 'utf-8')) as TreeSnapshot;
      if (raw?.v !== 1 || typeof raw.nodes !== 'object') return;
      this.nodes = new Map(Object.entries(raw.nodes));
      this.currentBySession = new Map(Object.entries(raw.currentBySession ?? {}));
      this.trajectorySession = new Map(Object.entries(raw.trajectorySession ?? {}));
    } catch {
      // Corrupt/unreadable snapshot — start fresh; the semantic trajectory
      // persistence in the 'trajectories' namespace is unaffected.
    }
  }

  private save(): void {
    try {
      const snapshot: TreeSnapshot = {
        v: 1,
        nodes: Object.fromEntries(this.nodes),
        currentBySession: Object.fromEntries(this.currentBySession),
        trajectorySession: Object.fromEntries(this.trajectorySession),
      };
      mkdirSync(dirname(this.persistPath), { recursive: true });
      writeFileSync(this.persistPath, JSON.stringify(snapshot), 'utf-8');
    } catch {
      // Best-effort — tree still lives in memory.
    }
  }
}

// ── Singleton (mirrors the lazy-singleton pattern used by model-router) ────

let treeInstance: TrajectoryTree | null = null;

export function getTrajectoryTree(persistPath?: string): TrajectoryTree {
  if (!treeInstance) treeInstance = new TrajectoryTree(persistPath);
  return treeInstance;
}

/** Test/reset hook — drops the singleton so the next get() reloads from disk. */
export function resetTrajectoryTree(): void {
  treeInstance = null;
}

export default TrajectoryTree;

/**
 * Vector Database Module
 *
 * Provides optional ruvector WASM-accelerated vector operations for:
 * - Semantic similarity search
 * - HNSW indexing (150x faster)
 * - Embedding generation
 *
 * Gracefully degrades when ruvector is not installed.
 *
 * Created with love by ruv.io
 */

import os from 'node:os';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

export interface VectorDB {
  insert(embedding: Float32Array, id: string, metadata?: Record<string, unknown>): void | Promise<void>;
  search(query: Float32Array, k?: number): Array<{ id: string; score: number; metadata?: Record<string, unknown> }> | Promise<Array<{ id: string; score: number; metadata?: Record<string, unknown> }>>;
  remove(id: string): boolean | Promise<boolean>;
  size(): number | Promise<number>;
  clear(): void | Promise<void>;
}

export interface RuVectorModule {
  createVectorDB(dimensions: number): Promise<VectorDB>;
  generateEmbedding(text: string, dimensions?: number): Float32Array;
  cosineSimilarity(a: Float32Array, b: Float32Array): number;
  isWASMAccelerated(): boolean;
}

// ============================================================================
// Fallback Implementation (when ruvector not available)
// ============================================================================

class FallbackVectorDB implements VectorDB {
  private vectors: Map<string, { embedding: Float32Array; metadata?: Record<string, unknown> }> = new Map();
  private dimensions: number;

  constructor(dimensions: number) {
    this.dimensions = dimensions;
  }

  insert(embedding: Float32Array, id: string, metadata?: Record<string, unknown>): void {
    this.vectors.set(id, { embedding, metadata });
  }

  search(query: Float32Array, k: number = 10): Array<{ id: string; score: number; metadata?: Record<string, unknown> }> {
    const results: Array<{ id: string; score: number; metadata?: Record<string, unknown> }> = [];

    for (const [id, { embedding, metadata }] of this.vectors) {
      const score = cosineSimilarity(query, embedding);
      results.push({ id, score, metadata });
    }

    return results
      .sort((a, b) => b.score - a.score)
      .slice(0, k);
  }

  remove(id: string): boolean {
    return this.vectors.delete(id);
  }

  size(): number {
    return this.vectors.size;
  }

  clear(): void {
    this.vectors.clear();
  }
}

/**
 * Compute cosine similarity between two vectors
 */
function cosineSimilarity(a: Float32Array, b: Float32Array): number {
  if (a.length !== b.length) {
    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
  }

  let dotProduct = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dotProduct / denom;
}

/**
 * Whether the hash-embedding one-time warning has been emitted
 */
let hashEmbeddingWarned = false;

/**
 * Generate a simple hash-based embedding (fallback when ruvector not available)
 * WARNING: Produces deterministic vectors with NO semantic meaning.
 */
function generateHashEmbedding(text: string, dimensions: number = 768): Float32Array {
  if (!hashEmbeddingWarned) {
    hashEmbeddingWarned = true;
    console.warn(
      '[vector-db] Using hash-based pseudo-embeddings (no semantic similarity). ' +
      'Install ruvector or @claude-flow/embeddings for real ML embeddings.'
    );
  }
  const embedding = new Float32Array(dimensions);
  const normalized = text.toLowerCase().trim();

  // Simple hash function
  let hash = 0;
  for (let i = 0; i < normalized.length; i++) {
    hash = ((hash << 5) - hash) + normalized.charCodeAt(i);
    hash = hash & hash; // Convert to 32bit integer
  }

  // Generate pseudo-random embedding based on hash
  for (let i = 0; i < dimensions; i++) {
    embedding[i] = Math.sin(hash * (i + 1) * 0.001) * 0.5 + 0.5;
  }

  // Normalize
  let norm = 0;
  for (let i = 0; i < dimensions; i++) {
    norm += embedding[i] * embedding[i];
  }
  norm = Math.sqrt(norm);
  for (let i = 0; i < dimensions; i++) {
    embedding[i] /= norm;
  }

  return embedding;
}

// ============================================================================
// Module State
// ============================================================================

let ruvectorModule: RuVectorModule | null = null;
let loadAttempted = false;
let isAvailable = false;

// ============================================================================
// Public API
// ============================================================================

/**
 * Attempt to load the ruvector module
 * Returns true if successfully loaded, false otherwise
 */
export async function loadRuVector(): Promise<boolean> {
  if (loadAttempted) {
    return isAvailable;
  }

  loadAttempted = true;

  try {
    // Dynamic import to handle missing dependency gracefully
    const ruvector = await import('ruvector').catch(() => null);

    // ruvector exports VectorDB class, not createVectorDB function
    if (ruvector && (typeof ruvector.VectorDB === 'function' || typeof ruvector.VectorDb === 'function')) {
      // Create adapter module that matches our expected interface
      const VectorDBClass = ruvector.VectorDB || ruvector.VectorDb;
      ruvectorModule = {
        createVectorDB: async (dimensions: number): Promise<VectorDB> => {
          // Build the HNSW graph with explicit, high-recall parameters instead
          // of relying on the native layer's undocumented defaults. Measured on
          // a 384-dim clustered corpus (scripts/benchmark-intelligence.mjs):
          //   - sparser graphs (e.g. m=16/efConstruction=64) are faster but
          //     drop recall@10 to ~0.68 at N=20k — unacceptable for a memory
          //     store, so we use the standard high-recall HNSW setting
          //     m=32/efConstruction=200, which keeps recall@10 ~0.99 while still
          //     scaling sub-linearly (log-graph traversal) above the crossover.
          // These map onto ruvector's DbOptions.hnsw { m, efConstruction }.
          //
          // storagePath: the native ruvector DB takes an exclusive file lock on
          // its storage path. Without an explicit path it defaults to a shared
          // file in the CWD (e.g. agentdb.rvf), which is frequently already
          // held by a running daemon/MCP server. When the lock cannot be
          // acquired the constructor THROWS, and createVectorDB() below
          // silently degrades to the O(n) brute-force FallbackVectorDB — so the
          // "HNSW" index is never actually used. Giving each transient index a
          // unique path avoids that contention so the real HNSW graph is built.
          const db = new VectorDBClass({
            dimensions,
            hnswConfig: { m: 32, efConstruction: 200 },
            storagePath: path.join(os.tmpdir(), `ruvector-${process.pid}-${randomUUID()}.rvf`),
          });
          // Wrap ruvector's VectorDB to match our interface
          return {
            insert: (embedding: Float32Array, id: string, metadata?: Record<string, unknown>) => {
              db.insert({ id, vector: embedding, metadata });
            },
            search: async (query: Float32Array, k: number = 10) => {
              const results = await db.search({ vector: query, k });
              return results.map((r: any) => ({
                id: r.id,
                score: r.score,
                metadata: r.metadata,
              }));
            },
            remove: (id: string) => {
              db.delete(id);
              return true;
            },
            size: async () => {
              const len = await db.len();
              return len;
            },
            clear: () => {
              // Not directly supported - would need to recreate
            },
          } as VectorDB;
        },
        generateEmbedding: (text: string, dimensions: number = 768): Float32Array => {
          // ruvector may not have this - use fallback
          return generateHashEmbedding(text, dimensions);
        },
        cosineSimilarity: (a: Float32Array, b: Float32Array): number => {
          return cosineSimilarity(a, b);
        },
        isWASMAccelerated: (): boolean => {
          return ruvector.isWasm?.() ?? false;
        },
      };
      isAvailable = true;
      return true;
    }
  } catch {
    // Silently fail - ruvector is optional
  }

  isAvailable = false;
  return false;
}

/**
 * Check if ruvector is available
 */
export function isRuVectorAvailable(): boolean {
  return isAvailable;
}

/**
 * Check if WASM acceleration is enabled
 */
export function isWASMAccelerated(): boolean {
  if (ruvectorModule && typeof ruvectorModule.isWASMAccelerated === 'function') {
    return ruvectorModule.isWASMAccelerated();
  }
  return false;
}

/**
 * Create a vector database
 * Uses ruvector HNSW if available, falls back to brute-force search
 */
export async function createVectorDB(dimensions: number = 768): Promise<VectorDB> {
  await loadRuVector();

  if (ruvectorModule && typeof ruvectorModule.createVectorDB === 'function') {
    try {
      return await ruvectorModule.createVectorDB(dimensions);
    } catch (err) {
      // Fall back to simple implementation, but make the degradation VISIBLE.
      // A silent fall-through here turns HNSW into O(n) brute force without any
      // signal — exactly the failure mode that masked the lock-contention bug.
      console.warn(
        `[vector-db] ruvector HNSW init failed, falling back to brute-force search: ${(err as Error)?.message ?? err}`
      );
    }
  }

  return new FallbackVectorDB(dimensions);
}

/**
 * Generate an embedding for text
 * Uses ruvector if available, falls back to hash-based embedding
 *
 * @returns The embedding vector. When using hash fallback, the returned
 *          Float32Array will have a `_warning` property (non-enumerable)
 *          indicating it lacks semantic meaning.
 */
export function generateEmbedding(text: string, dimensions: number = 768): Float32Array {
  if (ruvectorModule && typeof ruvectorModule.generateEmbedding === 'function') {
    try {
      return ruvectorModule.generateEmbedding(text, dimensions);
    } catch {
      // Fall back to hash-based embedding
    }
  }

  const embedding = generateHashEmbedding(text, dimensions);
  // Tag the result so consumers can detect it came from hash fallback
  Object.defineProperty(embedding, '_warning', {
    value: 'hash-based pseudo-embedding — no semantic similarity',
    enumerable: false,
    configurable: true,
  });
  return embedding;
}

/**
 * Compute cosine similarity between two vectors
 */
export function computeSimilarity(a: Float32Array, b: Float32Array): number {
  if (ruvectorModule && typeof ruvectorModule.cosineSimilarity === 'function') {
    try {
      return ruvectorModule.cosineSimilarity(a, b);
    } catch {
      // Fall back to JS implementation
    }
  }

  return cosineSimilarity(a, b);
}

/**
 * Get status information about the ruvector module
 */
export function getStatus(): {
  available: boolean;
  wasmAccelerated: boolean;
  backend: 'ruvector-stub-search-disabled' | 'ruvector-native' | 'fallback';
} {
  if (!isAvailable) {
    return {
      available: false,
      wasmAccelerated: false,
      backend: 'fallback',
    };
  }

  // HONESTY (audit docs/reviews/intelligence-system-audit-2026-05-29.md):
  // ruvector's `isWasm()` does NOT mean "WASM-accelerated" — there is no WASM
  // HNSW build in this stack. `isWasm()===true` means the do-nothing STUB is
  // active (search() returns []), i.e. native NAPI failed to load. So
  // wasmAccelerated===false is the HEALTHY state (native NAPI is the fastest
  // backend available). We label the stub honestly so a regression into it is
  // visible instead of being mistaken for a faster mode.
  const stubActive = isWASMAccelerated();
  return {
    available: true,
    wasmAccelerated: stubActive,
    backend: stubActive ? 'ruvector-stub-search-disabled' : 'ruvector-native',
  };
}
